const {
  app, BrowserWindow, Tray, Menu, screen, ipcMain, globalShortcut, nativeImage, shell, safeStorage, dialog,
} = require('electron');
const fs = require('fs');
const os = require('os');
const { createUpdater } = require('./updater');
const path = require('path');
const { spawn } = require('child_process');
const readline = require('readline');

const settings = require('./settings');
const { LyricsService, REGISTRY } = require('./lyrics');
const { stringifyLRC } = require('./lyrics/formats/lrc');
const selftest = require('./selftest');
const devchannel = require('./devchannel');
const wallpaperEngine = require('./wallpaperEngine');

const APP_DIR = path.resolve(app.getAppPath());
const ASSETS = path.join(APP_DIR, 'assets');
const ICON_ICO = path.join(ASSETS, 'icon.ico');
const REPO_URL = 'https://github.com/velibkolay/desktop-lyrics';
const LOG_FILE = app.isPackaged
  ? path.join(app.getPath('userData'), 'logs', 'app.log')
  : path.join(APP_DIR, 'logs', 'app.log');
// Inside the installed app, files that external programs read must live outside app.asar.
const unpacked = p => p.replace(/app\.asar([\\/])/, 'app.asar.unpacked$1');

/* ---------------- detach from the terminal ----------------
   Started with `npm start`: relaunch as a detached background process and let the terminal go. */
if (process.env.npm_lifecycle_event) {
  const env = { ...process.env };
  for (const k of Object.keys(env)) if (k.startsWith('npm_')) delete env[k];
  spawn(process.execPath, [APP_DIR], { detached: true, stdio: 'ignore', env, cwd: APP_DIR }).unref();
  console.log('Desktop Lyrics is running in the background (♪ in the tray). You can close this terminal.');
  process.exit(0);
}

/* ---------------- logging ---------------- */
(function setupLogging() {
  try {
    fs.mkdirSync(path.dirname(LOG_FILE), { recursive: true });
    if (fs.existsSync(LOG_FILE) && fs.statSync(LOG_FILE).size > 1_000_000) fs.writeFileSync(LOG_FILE, '');
  } catch { return; }
  for (const level of ['log', 'error']) {
    const original = console[level].bind(console);
    console[level] = (...args) => {
      original(...args);
      const text = args.map(a => (typeof a === 'string' ? a : a instanceof Error ? a.stack : JSON.stringify(a))).join(' ');
      try { fs.appendFileSync(LOG_FILE, `${new Date().toISOString()} ${level === 'error' ? 'ERROR ' : ''}${text}\n`); } catch { /* ignore */ }
    };
  }
  process.on('uncaughtException', e => console.error('uncaught:', e));
})();

if (!app.requestSingleInstanceLock()) {
  app.quit();
  return;
}
app.setAppUserModelId('desktop-lyrics');

let cfg;
let win;            // the lyrics overlay
let settingsWin;    // the settings window
let tray;
let bridge;
let quitting = false;
let editMode = false;
let overlayHidden = false;
let wallpaperKey = null;
let track = null;
let currentLyrics = null;
let currentArt = null;   // data: URL of the album art for the current track
let lyricsService = null;
let stopWallpaperWatch = null;
let lastBridgeError = null;

/* ================= settings & secrets ================= */

const SECRET_PREFIX = 'enc:';

function encrypt(value) {
  if (!value) return '';
  if (!safeStorage.isEncryptionAvailable()) return value;
  return SECRET_PREFIX + safeStorage.encryptString(value).toString('base64');
}

function decrypt(value) {
  if (typeof value !== 'string' || !value.startsWith(SECRET_PREFIX)) return value;
  try {
    return safeStorage.decryptString(Buffer.from(value.slice(SECRET_PREFIX.length), 'base64'));
  } catch (e) {
    console.error('[settings] could not decrypt a saved credential:', e.message);
    return '';
  }
}

function secretFields(providerId) {
  return new Set((REGISTRY[providerId]?.fields || []).filter(f => f.type === 'secret').map(f => f.key));
}

function currentLayout() {
  if (cfg.perWallpaperLayout && wallpaperKey && cfg.wallpaperLayouts[wallpaperKey]) {
    const own = cfg.wallpaperLayouts[wallpaperKey];
    return { ...cfg.layout, ...own, np: { ...cfg.layout.np, ...(own.np || {}) } };
  }
  return { ...cfg.layout, np: { ...cfg.layout.np } };
}

function layoutTarget() {
  return cfg.perWallpaperLayout && wallpaperKey ? `wallpaper ${wallpaperKey}` : 'the default layout';
}

function setLayout(patch) {
  if (cfg.perWallpaperLayout && wallpaperKey) {
    cfg.wallpaperLayouts[wallpaperKey] = { ...currentLayout(), ...patch };
  } else {
    Object.assign(cfg.layout, patch);
  }
  settings.save(cfg);
}

// "<Windows user>@<computer name>", like a real terminal prompt (Console look).
function defaultConsolePrompt() {
  let user = 'user';
  try { user = os.userInfo().username || user; } catch { /* no user info */ }
  return `${user}@${os.hostname() || 'desktop'}`.toLowerCase();
}

function pushSettings() {
  if (!win) return;
  win.webContents.send('settings', {
    look: settings.effectiveLook(cfg, wallpaperKey),
    decorations: cfg.decorations,
    consolePrompt: cfg.consolePrompt || defaultConsolePrompt(),
    style: cfg.style,
    layout: currentLayout(),
    nowPlaying: cfg.nowPlaying,
    offsetMs: cfg.offsetMs,
    trackOffsetMs: trackOffset(),
    hideWhenPaused: cfg.hideWhenPaused,
  });
}

// "SpotifyAB.SpotifyMusic_zpdnekdrzrea0!Spotify" → "spotify", "chrome.exe" → "chrome".
function playerName(appId) {
  const s = String(appId || '').split('!').pop().replace(/\.exe$/i, '').split('.').pop();
  return (s || 'player').toLowerCase();
}

function trackOffset() {
  return (track && cfg.trackOffsets[track.key]) || 0;
}

/** Everything the settings window shows. Credentials never leave the main process. */
function uiState() {
  const copy = structuredClone(cfg);
  const secretsSet = {};
  for (const [id, conf] of Object.entries(copy.providerConfig || {})) {
    for (const [k, v] of Object.entries(conf || {})) {
      if (typeof v === 'string' && (v.startsWith(SECRET_PREFIX) || secretFields(id).has(k))) {
        if (v) (secretsSet[id] ||= {})[k] = true;
        delete conf[k];
      }
    }
  }
  const primaryId = screen.getPrimaryDisplay().id;
  return {
    cfg: copy,
    secretsSet,
    layout: currentLayout(),
    layoutTarget: layoutTarget(),
    look: settings.effectiveLook(cfg, wallpaperKey),
    lookTarget: settings.lookTarget(cfg, wallpaperKey),
    consolePromptDefault: defaultConsolePrompt(),
    lookStyles: settings.LOOK_STYLES,
    providers: LyricsService.providers(),
    displays: screen.getAllDisplays().map((d, i) => ({
      index: i, label: `Display ${i + 1} — ${d.size.width}×${d.size.height}${d.id === primaryId ? ' (primary)' : ''}`,
    })),
    wallpaperKey,
    track,
    art: currentArt,
    lyricsSource: currentLyrics ? `${currentLyrics.sourceName}${currentLyrics.synced ? '' : ' (unsynced)'}` : null,
    lyricsSourceId: currentLyrics ? currentLyrics.source : null,
    pinned: track ? (cfg.trackOverrides[track.key] || {}).provider || null : null,
    trackOffsetMs: trackOffset(),
    localFolder: localFolder(),
    version: app.getVersion(),
    loginItem: app.getLoginItemSettings(loginItemOptions()).openAtLogin,
    update: updater.state,
    editMode,
  };
}

function sendState(partial) {
  if (settingsWin && !settingsWin.isDestroyed()) settingsWin.webContents.send('settings:state', partial);
}

function statusState() {
  const s = uiState();
  return {
    track: s.track, lyricsSource: s.lyricsSource, lyricsSourceId: s.lyricsSourceId,
    pinned: s.pinned, trackOffsetMs: s.trackOffsetMs,
    wallpaperKey: s.wallpaperKey, layout: s.layout, layoutTarget: s.layoutTarget, editMode: s.editMode,
    look: s.look, lookTarget: s.lookTarget,
  };
}

/** Applies a changed cfg everywhere. */
function applyConfig(previous) {
  settings.save(cfg);
  placeWindow();
  pushSettings();
  if (previous && previous.alwaysOnTop !== cfg.alwaysOnTop) applyLayer();
  if (previous && previous.player !== cfg.player && bridge) bridge.kill(); // restarts with the new player
  if (previous && previous.wallpaperEngineConfig !== cfg.wallpaperEngineConfig) watchWallpaper();
  updateTray();
}

function applyFileChange(next) {
  const previous = cfg;
  cfg = next;
  placeWindow();
  pushSettings();
  if (previous.alwaysOnTop !== cfg.alwaysOnTop) applyLayer();
  if (previous.player !== cfg.player && bridge) bridge.kill();
  if (previous.wallpaperEngineConfig !== cfg.wallpaperEngineConfig) watchWallpaper();
  updateTray();
  sendState(uiState());
}

/* ================= overlay window ================= */

function placeWindow() {
  if (!win) return;
  const displays = screen.getAllDisplays();
  const display = displays[cfg.display] || screen.getPrimaryDisplay();
  win.setBounds(display.workArea);
}

function setDisplay(index) {
  const count = screen.getAllDisplays().length;
  cfg.display = ((index % count) + count) % count;
  applyConfig();
  sendState({ cfg: uiState().cfg });
}

function setOverlayHidden(hidden) {
  overlayHidden = hidden;
  if (hidden) win.hide(); else win.showInactive();
  updateTray();
}

function changeTrackOffset(deltaMs) {
  if (!track) return;
  const next = deltaMs === null ? 0 : trackOffset() + deltaMs;
  if (next) cfg.trackOffsets[track.key] = next;
  else delete cfg.trackOffsets[track.key];
  applyConfig();
  sendState(statusState());
}

function changeOffset(deltaMs) {
  cfg.offsetMs = deltaMs === null ? 0 : cfg.offsetMs + deltaMs;
  applyConfig();
  sendState({ cfg: uiState().cfg });
}

function logRendererErrors(wc, name) {
  wc.on('console-message', (e, level, message, line, source) => {
    const lvl = e.level ?? level;
    const msg = e.message ?? message;
    if (lvl === 'error' || lvl === 3 || lvl === 'warning' || lvl === 2) {
      console.error(`[${name}] ${msg}${(e.lineNumber ?? line) ? ` (${path.basename(e.sourceId ?? source ?? '')}:${e.lineNumber ?? line})` : ''}`);
    }
  });
  wc.on('render-process-gone', (_e, details) => console.error(`[${name}] renderer gone: ${details.reason}`));
}

function createOverlay() {
  win = new BrowserWindow({
    show: false,
    frame: false,
    transparent: true,
    backgroundColor: '#00000000',
    hasShadow: false,
    resizable: false,
    movable: false,
    minimizable: false,
    maximizable: false,
    fullscreenable: false,
    skipTaskbar: true,
    focusable: false,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
      backgroundThrottling: false,
    },
  });
  win.setIgnoreMouseEvents(true);
  logRendererErrors(win.webContents, 'overlay');
  placeWindow();
  win.loadFile(path.join(__dirname, 'renderer', 'index.html'));

  win.webContents.once('did-finish-load', () => {
    win.showInactive();
    applyLayer();
    pushSettings();
    startBridge();
  });
}

/* ================= edit mode ================= */

const editFlagFile = () => path.join(app.getPath('userData'), 'edit-mode.flag');

function setEditFlag(on) {
  try {
    if (on) fs.writeFileSync(editFlagFile(), '1');
    else fs.rmSync(editFlagFile(), { force: true });
  } catch (e) {
    console.error('edit flag:', e.message);
  }
}

// Desktop layer (default): the bridge keeps the window at the bottom. "Always on top": above every
// window, still click-through; the flag file tells the bridge to stop pushing it down.
// ---- self-update (src/updater.js) ----
const updater = createUpdater({
  app,
  log: msg => console.log(msg),
  onChange: st => { updateTray(); sendState({ update: st }); },
});
function scheduleUpdateChecks() {
  if (!app.isPackaged) return; // source runs update with git
  const run = () => { if (cfg.autoUpdate) updater.check(); };
  setTimeout(run, 15000);
  setInterval(run, 6 * 3600 * 1000);
}

function applyLayer() {
  setEditFlag(editMode || !!cfg.alwaysOnTop);
  if (!win || win.isDestroyed() || editMode) return;
  if (cfg.alwaysOnTop) { win.setAlwaysOnTop(true, 'screen-saver'); win.moveTop(); } else win.setAlwaysOnTop(false);
}

function setAlwaysOnTop(on) {
  cfg.alwaysOnTop = !!on;
  settings.save(cfg);
  applyLayer();
  updateTray();
  sendState({ cfg: uiState().cfg });
}

// Normal mode: click-through, non-focusable, kept at the bottom by the bridge.
// Edit mode: on top of everything and clickable, so it can be dragged; the bridge pauses pinning.
function setEditMode(on) {
  editMode = on;
  setEditFlag(on || !!cfg.alwaysOnTop);
  if (on) {
    if (overlayHidden) setOverlayHidden(false);
    win.setFocusable(true);
    win.setIgnoreMouseEvents(false);
    win.setAlwaysOnTop(true, 'screen-saver');
    win.moveTop();
    win.focus();
  } else {
    win.setIgnoreMouseEvents(true);
    win.setFocusable(false);
    applyLayer();
  }
  win.webContents.send('edit-mode', on);
  updateTray();
  sendState(statusState());
}

ipcMain.on('edit-exit', () => { if (editMode) setEditMode(false); });

ipcMain.on('layout-update', (_event, layout) => {
  setLayout(layout);
  sendState({ layout: currentLayout() });
});

/* ================= Windows bridge (SMTC + desktop pinning) ================= */

function windowHandle() {
  const buf = win.getNativeWindowHandle();
  return (buf.length >= 8 ? buf.readBigUInt64LE(0) : BigInt(buf.readUInt32LE(0))).toString();
}

function startBridge() {
  const script = unpacked(path.join(__dirname, 'bridge.ps1'));
  bridge = spawn('powershell.exe', [
    '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', script,
    '-Player', cfg.player || '*',
    '-Hwnd', windowHandle(),
    '-ParentPid', String(process.pid),
    '-EditFlag', editFlagFile(),
  ], { windowsHide: true });

  readline.createInterface({ input: bridge.stdout }).on('line', onBridgeLine);
  bridge.stderr.on('data', d => console.error('[bridge]', d.toString().trim()));
  bridge.on('exit', () => {
    bridge = null;
    if (!quitting) setTimeout(startBridge, 2000);
  });
}

function onBridgeLine(line) {
  let msg;
  try {
    msg = JSON.parse(line.replace(/^﻿/, ''));
  } catch {
    return;
  }
  if (msg.type === 'error') {
    if (msg.message !== lastBridgeError) console.error('[bridge]', msg.message);
    lastBridgeError = msg.message;
    return;
  }
  lastBridgeError = null;
  if (msg.type === 'art') {
    if (track && msg.key === `${track.artist}|${track.title}`) {
      currentArt = msg.data ? `data:${msg.mime || 'image/jpeg'};base64,${msg.data}` : null;
      win.webContents.send('art', { key: track.key, src: currentArt });
      sendState({ art: currentArt });
    }
    return;
  }
  if (msg.type !== 'media') return;

  win.webContents.send('media', msg);

  const key = msg.title ? `${msg.artist || ''}|${msg.title}` : null;
  if (key === (track && track.key)) {
    if (track && !track.duration && msg.duration) track.duration = msg.duration;
    return;
  }

  track = key ? {
    key, title: msg.title, artist: msg.artist || '', album: msg.album || '', duration: msg.duration || 0,
    trackNumber: Number(msg.trackNumber) || 0, player: playerName(msg.app),
  } : null;
  currentLyrics = null;
  currentArt = null;
  win.webContents.send('track', track);
  pushSettings(); // per-song offset
  updateTray();
  sendState(statusState());
  // Give the bridge one more tick so the duration (used for matching) is known.
  if (track) { const t = track; setTimeout(() => { if (track === t) loadLyrics(t); }, 300); }
}

async function loadLyrics(t, { force = false } = {}) {
  const { lyrics: result, cached } = await lyricsService.find(t, { force });
  const what = result ? `${result.synced ? 'synced' : 'plain'} from ${result.sourceName}` : 'not found';
  console.log(`[lyrics] ${t.artist} — ${t.title}: ${what}${cached ? ' (cache)' : ''}`);
  if (!win || win.isDestroyed()) return; // app is restarting/quitting
  if (track && track.key === t.key) {
    currentLyrics = result;
    win.webContents.send('lyrics', { key: t.key, lyrics: result });
    updateTray();
    sendState(statusState());
  }
}

/* ================= Wallpaper Engine ================= */

function watchWallpaper() {
  if (stopWallpaperWatch) stopWallpaperWatch();
  stopWallpaperWatch = wallpaperEngine.watch(cfg.wallpaperEngineConfig, key => {
    wallpaperKey = key;
    pushSettings();
    updateTray();
    sendState(statusState());
  });
}

/* ================= local lyrics / per-song choices ================= */

function localFolder() {
  return (cfg.providerConfig.local || {}).folder || path.join(app.getPath('music'), 'Lyrics');
}

function localProviderCtx() {
  return lyricsService.context('local');
}

async function saveLocalLyrics(text, ext) {
  if (!track) throw new Error('Nothing is playing');
  const file = REGISTRY.local.save(track, text, localProviderCtx(), ext);
  delete cfg.trackOverrides[track.key]; // the local file should win
  applyConfig();
  await loadLyrics(track, { force: true });
  return file;
}

function summarize(r) {
  const l = r.lyrics;
  return {
    provider: r.provider,
    name: REGISTRY[r.provider]?.name || r.provider,
    ms: r.ms,
    error: r.error || null,
    reason: r.reason || null,
    match: r.match,
    found: !!l,
    synced: !!l?.synced,
    wordSynced: !!l?.wordSynced,
    lines: l?.lines?.length || 0,
    sample: l ? (l.synced ? l.lines.slice(0, 4).map(x => x.text) : (l.plain || '').split('\n').slice(0, 4)) : [],
  };
}

/* ================= settings window ================= */

function openSettings(page) {
  if (settingsWin && !settingsWin.isDestroyed()) {
    if (settingsWin.isMinimized()) settingsWin.restore();
    settingsWin.show();
    settingsWin.focus();
    return;
  }
  settingsWin = new BrowserWindow({
    width: 1060,
    height: 740,
    minWidth: 820,
    minHeight: 560,
    title: 'Desktop Lyrics — Settings',
    icon: ICON_ICO,
    backgroundColor: '#13111c',
    show: false,
    autoHideMenuBar: true,
    webPreferences: {
      preload: path.join(__dirname, 'settings-window', 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });
  settingsWin.setMenu(null);
  logRendererErrors(settingsWin.webContents, 'settings');
  settingsWin.loadFile(path.join(__dirname, 'settings-window', 'index.html'), page ? { hash: page } : undefined);
  settingsWin.once('ready-to-show', () => settingsWin.show());
  settingsWin.on('close', onSettingsClose);
  settingsWin.on('closed', () => { settingsWin = null; });
}

let trayHintShown = false;
function hideToTray() {
  settingsWin.hide();
  if (!trayHintShown && tray) {
    trayHintShown = true;
    tray.displayBalloon({ iconType: 'info', title: 'Desktop Lyrics', content: 'Still running — open it again from the Start menu or the tray icon.' });
  }
}

// X button: minimize to tray, quit, or ask (with "remember my choice").
function onSettingsClose(e) {
  if (quitting) return;
  const action = cfg.closeAction || 'ask';
  if (action === 'quit') { app.quit(); return; }
  e.preventDefault();
  if (action === 'tray') { hideToTray(); return; }
  dialog.showMessageBox(settingsWin, {
    type: 'question',
    title: 'Desktop Lyrics',
    message: 'Close Desktop Lyrics?',
    detail: 'Minimizing keeps the lyrics on your desktop; quitting stops them.',
    buttons: ['Minimize to tray', 'Quit', 'Cancel'],
    defaultId: 0,
    cancelId: 2,
    checkboxLabel: 'Remember my choice (change it in Settings → General)',
    noLink: true,
  }).then(({ response, checkboxChecked }) => {
    if (response === 2) return;
    if (checkboxChecked) {
      cfg.closeAction = response === 0 ? 'tray' : 'quit';
      settings.save(cfg);
      sendState({ cfg: uiState().cfg });
    }
    if (response === 0) hideToTray();
    else app.quit();
  });
}

let fontCache = null;
function listFonts() {
  if (fontCache) return fontCache;
  fontCache = new Promise(resolve => {
    const ps = spawn('powershell.exe', [
      '-NoProfile', '-NonInteractive', '-Command',
      '[Console]::OutputEncoding=[Text.Encoding]::UTF8; Add-Type -AssemblyName System.Drawing; ' +
      '(New-Object System.Drawing.Text.InstalledFontCollection).Families | ForEach-Object { $_.Name }',
    ], { windowsHide: true });
    let out = '';
    ps.stdout.on('data', d => { out += d; });
    ps.on('close', () => resolve([...new Set(out.split(/\r?\n/).map(s => s.trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b))));
    ps.on('error', () => resolve([]));
  });
  return fontCache;
}

ipcMain.handle('settings:get', () => uiState());

ipcMain.handle('settings:update', (_e, patch) => {
  const previous = structuredClone(cfg);
  if (patch.providerConfig) {
    for (const [id, conf] of Object.entries(patch.providerConfig)) {
      const secrets = secretFields(id);
      for (const [k, v] of Object.entries(conf)) {
        if (secrets.has(k)) conf[k] = encrypt(String(v || ''));
      }
    }
  }
  // A look picked while per-wallpaper looks are on belongs to the current wallpaper.
  if (patch.look !== undefined && !settings.LOOKS.includes(patch.look)) delete patch.look;
  if (patch.look !== undefined && settings.lookTarget({ ...cfg, ...patch }, wallpaperKey).wallpaper) {
    cfg.wallpaperLooks = { ...(cfg.wallpaperLooks || {}), [wallpaperKey]: patch.look };
    delete patch.look;
  }
  cfg = settings.merge(cfg, patch);
  if (patch.providers) cfg.providers = settings.normalizeProviders(patch.providers);
  applyConfig(previous);
  if (patch.providers || patch.providerConfig) lyricsService.clearMemory();
  return uiState();
});

ipcMain.handle('settings:layout', (_e, patch) => {
  setLayout(patch);
  pushSettings();
  return currentLayout();
});

ipcMain.handle('settings:fonts', () => listFonts());

function describeTest(r, t) {
  const head = `${t.artist} — ${t.title}\n`;
  if (r.error) return `${head}✗ ${r.error}  (${r.ms} ms)`;
  if (!r.lyrics) return `${head}✗ ${r.reason || 'nothing found'}  (${r.ms} ms)`;
  const l = r.lyrics;
  const kind = l.synced ? `synced, ${l.lines.length} lines${l.wordSynced ? ', word timing' : ''}` : 'unsynced text';
  const match = r.match ? `match "${r.match.title}" — ${r.match.artist} (score ${r.match.score})\n` : '';
  const sample = l.synced ? l.lines.slice(0, 3).map(x => `  ${x.start.toFixed(1).padStart(6)}s  ${x.text}`).join('\n') : `  ${(l.plain || '').split('\n').slice(0, 2).join(' / ')}`;
  return `${head}✓ ${kind}  (${r.ms} ms)\n${match}${sample}`;
}

ipcMain.handle('settings:action', async (_e, name, arg) => {
  switch (name) {
    case 'editMode':
      setEditMode(!editMode);
      return { message: editMode ? 'Adjust on the desktop — Esc to finish' : 'Done' };
    case 'refetch':
      if (!track) return { message: 'Nothing is playing' };
      await loadLyrics(track, { force: true });
      return { message: currentLyrics ? `Found on ${currentLyrics.sourceName}` : 'No lyrics found' };
    case 'testProvider': {
      const provider = REGISTRY[arg];
      const t = track || { ...selftest.DEFAULT_TRACKS[0], key: 'selftest' };
      const r = await lyricsService.runProvider(provider, t);
      return { text: describeTest(r, t) };
    }
    case 'resetWallpaperLayout':
      if (!wallpaperKey || !cfg.wallpaperLayouts[wallpaperKey]) return { message: 'Nothing to reset' };
      delete cfg.wallpaperLayouts[wallpaperKey];
      applyConfig();
      return { message: 'Layout reset', state: uiState() };
    case 'setLoginItem':
      app.setLoginItemSettings({ openAtLogin: !!arg, ...loginItemOptions() });
      updateTray();
      return { message: arg ? 'Starts with Windows' : 'Won\'t start with Windows' };
    case 'createShortcuts':
      createShortcuts();
      return { message: 'Shortcuts created' };
    case 'openLog':
      shell.openPath(LOG_FILE);
      return null;
    case 'openSettingsFile':
      shell.openPath(settings.file());
      return null;
    case 'openRepo':
      shell.openExternal(REPO_URL);
      return null;
    case 'exportSettings': {
      const { canceled, filePath } = await dialog.showSaveDialog(settingsWin, {
        title: 'Export settings', defaultPath: 'desktop-lyrics-settings.json', filters: [{ name: 'JSON', extensions: ['json'] }],
      });
      if (canceled) return null;
      const out = uiState().cfg; // without credentials
      fs.writeFileSync(filePath, JSON.stringify(out, null, 2));
      return { message: 'Settings exported (without credentials)' };
    }
    case 'importSettings': {
      const { canceled, filePaths } = await dialog.showOpenDialog(settingsWin, {
        title: 'Import settings', properties: ['openFile'], filters: [{ name: 'JSON', extensions: ['json'] }],
      });
      if (canceled || !filePaths[0]) return null;
      try {
        const imported = JSON.parse(fs.readFileSync(filePaths[0], 'utf8'));
        const previous = structuredClone(cfg);
        const keepSecrets = cfg.providerConfig;
        cfg = settings.merge(settings.DEFAULTS, imported);
        cfg.providers = settings.normalizeProviders(cfg.providers);
        cfg.providerConfig = settings.merge(imported.providerConfig || {}, keepSecrets);
        cfg.setupDone = true;
        applyConfig(previous);
        return { message: 'Settings imported', state: uiState() };
      } catch (e) {
        return { message: `Import failed: ${e.message}` };
      }
    }
    case 'compare': {
      if (!track) return { message: 'Nothing is playing', results: [] };
      const results = await lyricsService.compare(track);
      return { results: results.map(summarize) };
    }
    case 'pin':
      if (!track) return { message: 'Nothing is playing' };
      cfg.trackOverrides[track.key] = { provider: arg };
      applyConfig();
      await loadLyrics(track, { force: true });
      return { message: `Using ${REGISTRY[arg]?.name || arg} for this song`, state: uiState() };
    case 'unpin':
      if (!track) return { message: 'Nothing is playing' };
      delete cfg.trackOverrides[track.key];
      applyConfig();
      await loadLyrics(track, { force: true });
      return { message: 'Back to automatic choice', state: uiState() };
    case 'importLyrics': {
      if (!track) return { message: 'Play the song first' };
      const { canceled, filePaths } = await dialog.showOpenDialog(settingsWin, {
        title: `Lyrics for ${track.artist} — ${track.title}`,
        properties: ['openFile'],
        filters: [{ name: 'Lyrics', extensions: ['lrc', 'ttml', 'xml', 'txt'] }],
      });
      if (canceled || !filePaths[0]) return null;
      const file = await saveLocalLyrics(fs.readFileSync(filePaths[0], 'utf8'), path.extname(filePaths[0]).toLowerCase());
      return { message: `Saved as ${path.basename(file)}`, state: uiState() };
    }
    case 'pasteLyrics': {
      if (!track) return { message: 'Play the song first' };
      if (!arg || !String(arg).trim()) return { message: 'Nothing to save' };
      const file = await saveLocalLyrics(String(arg));
      return { message: `Saved as ${path.basename(file)}`, state: uiState() };
    }
    case 'saveAsLocal': {
      if (!track || !currentLyrics) return { message: 'No lyrics to save' };
      const text = currentLyrics.synced
        ? stringifyLRC(currentLyrics.lines, { title: track.title, artist: track.artist, album: track.album })
        : currentLyrics.plain;
      const file = REGISTRY.local.save(track, text, localProviderCtx(), currentLyrics.synced ? '.lrc' : '.txt');
      return { message: `Saved ${path.basename(file)} — edit it to fix lines` };
    }
    case 'openLyricsFolder':
      fs.mkdirSync(localFolder(), { recursive: true });
      shell.openPath(localFolder());
      return null;
    case 'setTrackOffset':
      if (!track) return { message: 'Nothing is playing' };
      changeTrackOffset(null);
      changeTrackOffset(Number(arg) || 0);
      return null;
    case 'restart':
      restart('settings window');
      return null;
    case 'checkUpdates':
      return updater.check({ manual: true });
    case 'installUpdate':
      return updater.install();
    case 'quit':
      app.quit();
      return null;
    default:
      return { message: `Unknown action ${name}` };
  }
});

/* ================= dev channel (source runs only) ================= */

function devHandlers() {
  const logsDir = path.dirname(LOG_FILE);
  const target = name => {
    const w = name === 'overlay' ? win : settingsWin;
    if (!w || w.isDestroyed()) throw new Error(`${name} window is not open`);
    return w;
  };
  return {
    state: () => ({ ...uiState(), overlayHidden, bounds: win.getBounds(), onTop: win.isAlwaysOnTop() }),
    wait: ({ ms = 500 }) => new Promise(r => setTimeout(r, ms)),
    openSettings: async ({ page }) => {
      openSettings(page);
      if (page) {
        await new Promise(r => setTimeout(r, 600));
        await settingsWin.webContents.executeJavaScript(`document.querySelector('nav button[data-page="${page}"]')?.click()`);
      }
      return true;
    },
    // hide, never close: closing can mean "quit" (closeAction) and would end the app mid-test
    closeSettings: () => { if (settingsWin && !settingsWin.isDestroyed()) settingsWin.hide(); return true; },
    eval: ({ target: t = 'settings', js }) => target(t).webContents.executeJavaScript(js),
    screenshot: async ({ target: t = 'settings', file }) => {
      const img = await target(t).webContents.capturePage();
      const out = path.join(logsDir, file || `${t}.png`);
      fs.writeFileSync(out, img.toPNG());
      return { file: path.basename(out), size: img.getSize() };
    },
    editMode: ({ on = true }) => { setEditMode(!!on); return editMode; },
    // Downloads a URL from this machine (which has normal internet access) into logs/.
    fetch: async ({ url, file, headers = {}, method = 'GET', body }) => {
      const res = await fetch(url, {
        method,
        body,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0 Safari/537.36',
          ...headers,
        },
      });
      const buf = Buffer.from(await res.arrayBuffer());
      const out = path.join(logsDir, path.basename(file || 'fetch.bin'));
      fs.writeFileSync(out, buf);
      return { status: res.status, bytes: buf.length, type: res.headers.get('content-type'), file: path.basename(out) };
    },
    selftest: req => selftest.run(lyricsService, logsDir, req),
    // Runs an async JS snippet in the main process (dev builds only). `require` and the app's modules are in scope.
    mainEval: async ({ js }) => {
      const fn = new Function('require', 'REGISTRY', 'lyricsService', `return (async () => { ${js} })();`);
      return fn(require, REGISTRY, lyricsService);
    },
    // Raw search results of one provider, for debugging matching.
    search: async ({ provider, title, artist, duration = 0 }) => {
      const t = { key: 'dev', title, artist, duration };
      const cands = await REGISTRY[provider].search(t, lyricsService.context(provider));
      const { score } = require('./lyrics/match');
      return (cands || []).slice(0, 10).map(c => ({ ...c, raw: undefined, score: score(t, c) }));
    },
  };
}

/* ================= shortcuts, autostart, restart ================= */

// The portable build runs from a temporary folder; the real exe path is in this variable.
const EXE = process.env.PORTABLE_EXECUTABLE_FILE || process.execPath;

const START_HIDDEN = process.argv.includes('--hidden');

function loginItemOptions() {
  return { path: EXE, args: app.isPackaged ? ['--hidden'] : [APP_DIR, '--hidden'] };
}

// Older versions registered autostart without --hidden; refresh the entry once.
function refreshLoginItem() {
  const old = { path: EXE, args: app.isPackaged ? [] : [APP_DIR] };
  if (app.getLoginItemSettings(old).openAtLogin) {
    app.setLoginItemSettings({ openAtLogin: false, ...old });
    app.setLoginItemSettings({ openAtLogin: true, ...loginItemOptions() });
  }
}

// When the app icon changes, re-create shortcuts that still exist (deleted ones stay deleted).
function refreshShortcutIcons() {
  let hash;
  try { hash = require('crypto').createHash('sha1').update(fs.readFileSync(ICON_ICO)).digest('hex').slice(0, 12); } catch { return; }
  if (cfg.shortcutIconHash === hash) return;
  const existing = shortcutPlaces().filter(p => fs.existsSync(p));
  if (existing.length) createShortcuts(existing);
  cfg.shortcutIconHash = hash;
  settings.save(cfg);
}

function shortcutPlaces() {
  return [
    path.join(app.getPath('desktop'), 'Desktop Lyrics.lnk'),
    path.join(app.getPath('appData'), 'Microsoft', 'Windows', 'Start Menu', 'Programs', 'Desktop Lyrics.lnk'),
  ];
}

function createShortcuts(places = shortcutPlaces()) {
  const options = {
    target: EXE,
    args: app.isPackaged ? '' : `"${APP_DIR}"`,
    cwd: app.isPackaged ? path.dirname(EXE) : APP_DIR,
    icon: ICON_ICO,
    iconIndex: 0,
    description: 'Desktop Lyrics',
    appUserModelId: 'desktop-lyrics',
  };
  for (const place of places) {
    const ok = shell.writeShortcutLink(place, fs.existsSync(place) ? 'replace' : 'create', options);
    console.log(`[setup] shortcut ${place}: ${ok ? 'ok' : 'FAILED'}`);
  }
}

// Runs once. Shortcuts the user deletes later are not re-created.
function firstRunSetup() {
  if (cfg.setupDone) return;
  // The installer creates shortcuts; dev runs and the portable exe create their own.
  if (!app.isPackaged || process.env.PORTABLE_EXECUTABLE_FILE) createShortcuts();
  app.setLoginItemSettings({ openAtLogin: true, ...loginItemOptions() });
  cfg.setupDone = true;
  settings.save(cfg);
  openSettings();
}

function restart(reason) {
  console.log(`[app] restarting: ${reason}`);
  quitting = true;
  setEditFlag(false);
  if (bridge) bridge.kill();
  // Dev auto-restarts and tray restarts keep the window state: hidden stays hidden.
  const visible = settingsWin && !settingsWin.isDestroyed() && settingsWin.isVisible();
  const args = app.isPackaged ? [] : [APP_DIR];
  if (!visible) args.push('--hidden');
  app.relaunch({ execPath: EXE, args });
  app.exit(0);
}

// Development convenience: any change under src/ restarts the app.
function watchSource() {
  if (app.isPackaged) return;
  let timer;
  fs.watch(__dirname, { recursive: true }, (_event, file) => {
    clearTimeout(timer);
    timer = setTimeout(() => restart(`${file} changed`), 800);
  });
}

/* ================= tray ================= */

function displayMenu() {
  const primaryId = screen.getPrimaryDisplay().id;
  return screen.getAllDisplays().map((d, i) => ({
    label: `Display ${i + 1}  (${d.size.width}×${d.size.height}${d.id === primaryId ? ', primary' : ''})`,
    type: 'radio',
    checked: i === cfg.display,
    click: () => setDisplay(i),
  }));
}

function updateTray() {
  if (!tray) return;
  const lyricsLabel = !track ? '—' : currentLyrics ? `${currentLyrics.sourceName}${currentLyrics.synced ? '' : ' (unsynced)'}` : 'not found / searching';
  tray.setToolTip(track ? `Desktop Lyrics — ${track.title}` : 'Desktop Lyrics');
  tray.setContextMenu(Menu.buildFromTemplate([
    { label: track ? `♪ ${track.title} — ${track.artist}`.slice(0, 80) : '♪ Nothing playing', enabled: false },
    { label: `Lyrics: ${lyricsLabel}`, enabled: false },
    { type: 'separator' },
    ...(updater.state.status === 'ready' ? [{ label: `Restart to update to ${updater.state.version}`, click: () => updater.install() }] : []),
    { label: 'Settings…', click: () => openSettings() },
    { label: 'Adjust position   Ctrl+Alt+L', type: 'checkbox', checked: editMode, click: () => setEditMode(!editMode) },
    { label: 'Hide lyrics   Ctrl+Alt+H', type: 'checkbox', checked: overlayHidden, click: () => setOverlayHidden(!overlayHidden) },
    { label: 'Always on top   Ctrl+Alt+T', type: 'checkbox', checked: !!cfg.alwaysOnTop, click: () => setAlwaysOnTop(!cfg.alwaysOnTop) },
    { label: 'Display   Ctrl+Alt+M', submenu: displayMenu() },
    { type: 'separator' },
    { label: 'Lyrics earlier (+250 ms)   Ctrl+Alt+→', click: () => changeOffset(250) },
    { label: 'Lyrics later (−250 ms)   Ctrl+Alt+←', click: () => changeOffset(-250) },
    { label: `Reset offset (now ${cfg.offsetMs} ms)`, click: () => changeOffset(null) },
    { label: `This song: ${trackOffset()} ms   Ctrl+Alt+Shift+→/←`, enabled: !!track, click: () => changeTrackOffset(null) },
    { label: 'Search lyrics again', enabled: !!track, click: () => loadLyrics(track, { force: true }) },
    { type: 'separator' },
    { label: 'Restart', click: () => restart('tray') },
    { label: 'Quit', click: () => app.quit() },
  ]));
}

/* ================= startup ================= */

app.whenReady().then(() => {
  try {
    cfg = settings.load();
  } catch (e) {
    console.error('settings.json is invalid, using defaults:', e.message);
    cfg = structuredClone(settings.DEFAULTS);
  }

  lyricsService = new LyricsService({
    cacheDir: path.join(app.getPath('userData'), 'lyrics-cache'),
    getConfig: () => cfg,
    decrypt,
    defaults: { localFolder: path.join(app.getPath('music'), 'Lyrics') },
    log: msg => console.log(msg),
  });
  if (!app.isPackaged) {
    selftest.watch(lyricsService, path.dirname(LOG_FILE), msg => console.log(msg));
    devchannel.watch(path.dirname(LOG_FILE), devHandlers(), msg => console.log(msg));
  }

  applyLayer(); // also clears a leftover edit flag from a crash during edit mode
  scheduleUpdateChecks();
  createOverlay();
  watchWallpaper();
  settings.watch(applyFileChange);

  tray = new Tray(nativeImage.createFromPath(ICON_ICO));
  tray.on('click', () => openSettings());
  updateTray();
  const firstRun = !cfg.setupDone;
  firstRunSetup();
  refreshLoginItem();
  if (!app.isPackaged || process.env.PORTABLE_EXECUTABLE_FILE) refreshShortcutIcons();
  if (!firstRun && !START_HIDDEN) openSettings();
  watchSource();
  console.log(`[app] started v${app.getVersion()} (electron ${process.versions.electron}, ${app.isPackaged ? 'installed' : 'dev'}, display ${cfg.display}, player "${cfg.player}")`);

  app.on('second-instance', () => openSettings());

  const shortcuts = {
    'CommandOrControl+Alt+L': () => setEditMode(!editMode),
    'CommandOrControl+Alt+H': () => setOverlayHidden(!overlayHidden),
    'CommandOrControl+Alt+M': () => setDisplay(cfg.display + 1),
    'CommandOrControl+Alt+T': () => setAlwaysOnTop(!cfg.alwaysOnTop),
    'CommandOrControl+Alt+Right': () => changeOffset(250),
    'CommandOrControl+Alt+Left': () => changeOffset(-250),
    'CommandOrControl+Alt+Shift+Right': () => changeTrackOffset(250),
    'CommandOrControl+Alt+Shift+Left': () => changeTrackOffset(-250),
  };
  for (const [accel, fn] of Object.entries(shortcuts)) {
    if (!globalShortcut.register(accel, fn)) console.error(`[app] shortcut ${accel} is taken by another program`);
  }

  const displaysChanged = () => { placeWindow(); updateTray(); sendState({ cfg: uiState().cfg, displays: uiState().displays }); };
  screen.on('display-added', displaysChanged);
  screen.on('display-removed', displaysChanged);
  screen.on('display-metrics-changed', placeWindow);
});

app.on('before-quit', () => {
  quitting = true;
  setEditFlag(false);
  if (bridge) bridge.kill();
});

app.on('will-quit', () => globalShortcut.unregisterAll());
app.on('window-all-closed', () => { /* the overlay keeps the app alive; closing settings must not quit */ });

changes.before:
const api = window.settingsApi;
const $ = sel => document.querySelector(sel);
const $$ = sel => [...document.querySelectorAll(sel)];

let state = null;

const PRESETS = [
  { name: 'Classic', note: 'White, soft glow', style: { activeColor: '#ffffff', inactiveColor: '#ffffff', inactiveOpacity: 0.35, activeScale: 1.08, glow: 12, shadow: 6, blur: 1, bold: true } },
  { name: 'Neon', note: 'Cyan & violet', style: { activeColor: '#7df9ff', inactiveColor: '#c39bff', inactiveOpacity: 0.45, activeScale: 1.1, glow: 26, shadow: 4, blur: 0.5, bold: true } },
  { name: 'Sunset', note: 'Warm gold', style: { activeColor: '#ffd27f', inactiveColor: '#ffb3c7', inactiveOpacity: 0.4, activeScale: 1.08, glow: 18, shadow: 6, blur: 1, bold: true } },
  { name: 'Minimal', note: 'No glow, crisp', style: { activeColor: '#ffffff', inactiveColor: '#ffffff', inactiveOpacity: 0.25, activeScale: 1, glow: 0, shadow: 3, blur: 0, bold: false } },
  { name: 'Karaoke', note: 'Big yellow line', style: { activeColor: '#ffe066', inactiveColor: '#ffffff', inactiveOpacity: 0.3, activeScale: 1.2, glow: 14, shadow: 8, blur: 1.5, bold: true } },
  { name: 'Ghost', note: 'Subtle, low contrast', style: { activeColor: '#e8e4ff', inactiveColor: '#e8e4ff', inactiveOpacity: 0.15, activeScale: 1.04, glow: 6, shadow: 10, blur: 2, bold: false } },
];

/* ---------------- helpers ---------------- */

function debounce(fn, ms) {
  let t;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}

function toast(text) {
  const el = $('#toast');
  el.textContent = text;
  el.classList.add('show');
  clearTimeout(toast.t);
  toast.t = setTimeout(() => el.classList.remove('show'), 2200);
}

function valueOf(input) {
  if (input.type === 'checkbox') return input.checked;
  if (input.type === 'range' || input.type === 'number') return Number(input.value);
  return input.value;
}

function setInput(input, value) {
  if (value === undefined) return;
  if (input.type === 'checkbox') input.checked = !!value;
  else input.value = value;
  const out = input.parentElement.querySelector('output');
  if (out) out.textContent = formatOut(input, value);
}

function formatOut(input, v) {
  const step = Number(input.step || 1);
  return step < 1 ? Number(v).toFixed(step < 0.1 ? 2 : 1) : String(v);
}

const sendStyle = debounce(patch => api.update({ style: patch }), 80);
const sendLayout = debounce(patch => api.updateLayout(patch), 80);
const sendCfg = debounce(patch => api.update(patch), 80);

let pendingStyle = {}, pendingLayout = {}, pendingCfg = {};
const flushStyle = () => { const p = pendingStyle; pendingStyle = {}; sendStyle(p); };
const flushLayout = () => { const p = pendingLayout; pendingLayout = {}; sendLayout(p); };

/* ---------------- preview ---------------- */

function renderPreview() {
  const s = state.cfg.style;
  const box = $('#preview');
  box.style.fontFamily = `'${s.fontFamily}', 'Segoe UI', sans-serif`;
  box.querySelector('.pv-meta').style.display = s.showTitle ? '' : 'none';
  box.querySelector('.pv-meta').textContent = 'Song Title — Artist' + (s.showSource ? '  ·  LRCLIB' : '');
  for (const el of box.querySelectorAll('.pv-l')) {
    const active = el.classList.contains('pv-a');
    el.style.fontWeight = s.bold ? 700 : 400;
    el.style.lineHeight = s.lineHeight;
    el.style.color = active ? s.activeColor : s.inactiveColor;
    el.style.opacity = active ? 1 : s.inactiveOpacity;
    el.style.filter = active ? 'none' : `blur(${s.blur}px)`;
    el.style.transform = active ? `scale(${s.activeScale})` : 'none';
    el.style.textShadow = active
      ? `0 0 ${s.glow}px ${s.activeColor}, 0 2px ${s.shadow}px rgba(0,0,0,.9)`
      : `0 2px ${s.shadow}px rgba(0,0,0,.85)`;
  }
}

/* ---------------- render state into the form ---------------- */

// The look shown is the one in effect (the wallpaper's own one when per-wallpaper looks are on).
const ACCENT_PAIRS = [['#9b6bff', '#ff5fa2'], ['#2dd4ff', '#7b6bff'], ['#ffb347', '#ff5f6d'], ['#5be3b0', '#2a9dff']];

const LOOK_PICKS = [['classic', 'Classic', 'Aa'], ['aurora', 'Aurora', 'Aa'], ['neon', 'Neon', 'Neon'], ['magazine', 'Magazine', 'Lyric'], ['console', 'Console', '&gt;_'], ['island', 'Island', '']];

function renderLook() {
  const look = state.look || state.cfg.look || 'classic';
  $('#look').value = look;
  for (const b of $$('.look-pick')) { const on = b.dataset.look === look; b.classList.toggle('on', on); b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }
  for (const el of $$('.look-only')) el.hidden = el.dataset.for !== look;
  const pv = $('#preview');
  pv.dataset.look = look;
  pv.style.setProperty('--pv-a1', (state.cfg.style || {}).activeColor || '#9b6bff');
  pv.style.setProperty('--pv-a2', (state.cfg.style || {}).activeColor2 || '#ff5fa2');
  const st = state.cfg.style || {};
  for (const b of $$('#effectSeg button')) b.classList.toggle('on', b.value === (st.effect || 'karaoke'));
  for (const b of $$('#accentPairs button')) b.classList.toggle('on', b.dataset.a1 === st.activeColor && b.dataset.a2 === st.activeColor2);
  const t = state.lookTarget || {};
  $('#lookTarget').textContent = t.wallpaper ? `for wallpaper ${t.wallpaper}` : 'for all wallpapers';
  $('#consolePrompt').placeholder = state.consolePromptDefault || '';
}

function renderForm() {
  const { cfg, layout } = state;
  for (const el of $$('[data-style]')) setInput(el, cfg.style[el.dataset.style]);
  for (const el of $$('[data-layout]')) setInput(el, layout[el.dataset.layout]);
  for (const el of $$('[data-cfg]')) setInput(el, cfg[el.dataset.cfg]);
  for (const el of $$('[data-np]')) setInput(el, (cfg.nowPlaying || {})[el.dataset.np]);
  for (const el of $$('[data-deco]')) setInput(el, (cfg.decorations || {})[el.dataset.deco]);
  renderLook();
  for (const el of $$('[data-np-layout]')) setInput(el, (layout.np || {})[el.dataset.npLayout]);
  for (const seg of $$('[data-layout-seg]')) {
    for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.value === layout[seg.dataset.layoutSeg]);
  }

  const known = ['auto', 'Spotify', '*'];
  const isCustom = !known.includes(cfg.player);
  for (const b of $$('#playerSeg button')) b.classList.toggle('on', isCustom ? b.value === 'custom' : b.value === cfg.player);
  $('#playerCustomRow').hidden = !isCustom;
  if (isCustom && document.activeElement !== $('#playerCustom')) $('#playerCustom').value = cfg.player;

  $('#display').innerHTML = state.displays.map(d => `<option value="${d.index}">${d.label}</option>`).join('');
  $('#display').value = String(cfg.display);
  $('#loginItem').checked = state.loginItem;
  for (const b of $$('#closeSeg button')) b.classList.toggle('on', b.value === (cfg.closeAction || 'ask'));
  $('#version').textContent = state.version;
  renderStatus();
  renderPreview();
}

function renderSong() {
  const t = state.track;
  $('#songTitle').textContent = t ? `${t.title} — ${t.artist}` : 'Nothing playing';
  const pinnedName = state.pinned ? (state.providers.find(p => p.id === state.pinned)?.name || state.pinned) : null;
  $('#songSource').textContent = !t ? 'Start a song to compare sources or import lyrics.'
    : `${state.lyricsSource ? `Lyrics from ${state.lyricsSource}` : 'No lyrics found'}${pinnedName ? ` · pinned to ${pinnedName}` : ''}`;
  $('#unpinBtn').hidden = !state.pinned;
  const off = $('#trackOffset');
  if (document.activeElement !== off) setInput(off, state.trackOffsetMs || 0);
  off.disabled = !t;
}

async function runCompare() {
  const box = $('#compare');
  box.hidden = false;
  box.innerHTML = '<div class="muted small">Searching every enabled source…</div>';
  const { results = [], message } = await api.action('compare');
  if (message && !results.length) { box.innerHTML = `<div class="muted small">${message}</div>`; return; }
  box.innerHTML = '';
  for (const r of results) {
    const el = document.createElement('div');
    el.className = 'cmp' + (state.pinned === r.provider ? ' pinned' : '');
    const kind = r.error ? `error: ${r.error}` : !r.found ? (r.reason || 'nothing found')
      : `${r.synced ? `synced · ${r.lines} lines` : 'unsynced'}${r.wordSynced ? ' · word timing' : ''}`;
    el.innerHTML = `
      <div><div class="cmp-name"></div><div class="cmp-meta"></div></div>
      <div class="cmp-sample${r.found ? '' : ' none'}"></div>
      <div>${r.found ? `<button data-pin="${r.provider}">${state.pinned === r.provider ? 'Pinned' : 'Use for this song'}</button>` : ''}</div>`;
    el.querySelector('.cmp-name').textContent = r.name;
    el.querySelector('.cmp-meta').textContent = `${kind} · ${r.ms} ms${r.match ? ` · score ${r.match.score}` : ''}`;
    el.querySelector('.cmp-sample').textContent = r.found ? r.sample.join('\n') : '—';
    box.appendChild(el);
  }
}

function renderStatus() {
  renderSong();
  const art = $('#nowArt');
  if (state.art) { art.src = state.art; art.hidden = false; } else { art.hidden = true; art.removeAttribute('src'); }
  const t = state.track;
  $('#nowTitle').textContent = t ? `${t.title} — ${t.artist}` : 'Nothing playing';
  $('#nowSource').textContent = t ? `${t.player || 'player'} · ${state.lyricsSource || 'no lyrics'}` : '';
  $('#layoutTarget').textContent = `· saved for ${state.layoutTarget}`;
  $('#wallpaperInfo').textContent = state.wallpaperKey
    ? `Current Wallpaper Engine wallpaper: ${state.wallpaperKey}`
    : 'No Wallpaper Engine wallpaper detected — the default layout is used.';
  for (const card of $$('.provider')) {
    const badge = card.querySelector('.badge.current');
    if (badge) badge.hidden = state.lyricsSourceId !== card.dataset.id;
  }
}

/* ---------------- providers ---------------- */

function providerList() {
  return state.cfg.providers.filter(p => state.providers.some(r => r.id === p.id));
}

function renderProviders() {
  const wrap = $('#providers');
  wrap.innerHTML = '';
  providerList().forEach((entry, i) => {
    const info = state.providers.find(p => p.id === entry.id);
    const card = document.createElement('div');
    card.className = 'provider';
    card.dataset.id = entry.id;
    card.draggable = true;
    const secrets = (state.secretsSet || {})[entry.id] || {};
    const conf = state.cfg.providerConfig[entry.id] || {};
    const needsSetup = info.fields.some(f => f.required && !(f.type === 'secret' ? secrets[f.key] : conf[f.key]));
    card.innerHTML = `
      <div class="provider-head">
        <span class="grip" title="Drag to reorder">⠿</span>
        <span class="prio">${i + 1}</span>
        <div>
          <div class="provider-name">${info.name}</div>
          <div class="provider-desc">${info.description}</div>
        </div>
        <span class="spacer"></span>
        <span class="badge current" hidden>in use</span>
        ${needsSetup ? '<span class="badge warn">needs setup</span>' : ''}
        <button class="test">Test</button>
        <input type="checkbox" class="switch toggle" ${entry.enabled ? 'checked' : ''}>
      </div>
      ${info.fields.length ? `<div class="provider-body">${info.fields.map(f => fieldHtml(entry.id, f, conf, secrets)).join('')}</div>` : ''}
      <div class="test-result" hidden></div>`;
    wrap.appendChild(card);
  });
  renderStatus();
}

function fieldHtml(id, f, conf, secrets) {
  const isSecret = f.type === 'secret';
  const value = isSecret ? '' : (conf[f.key] ?? '');
  const placeholder = isSecret ? (secrets[f.key] ? 'Saved — paste a new value to replace' : f.placeholder || '') : f.placeholder || '';
  return `
    <label class="row">${f.label}
      <input data-provider="${id}" data-field="${f.key}" data-secret="${isSecret}" type="${isSecret ? 'password' : 'text'}"
             value="${String(value).replace(/"/g, '&quot;')}" placeholder="${placeholder}" spellcheck="false">
    </label>
    ${f.help ? `<div class="help">${f.help}</div>` : ''}`;
}

function saveProviderOrder() {
  const order = $$('.provider').map(c => ({ id: c.dataset.id, enabled: c.querySelector('.toggle').checked }));
  const rest = state.cfg.providers.filter(p => !order.some(o => o.id === p.id));
  state.cfg.providers = [...order, ...rest];
  api.update({ providers: state.cfg.providers });
  $$('.provider .prio').forEach((el, i) => { el.textContent = i + 1; });
}

function wireProviders() {
  const wrap = $('#providers');
  let dragged = null;

  wrap.addEventListener('dragstart', e => {
    dragged = e.target.closest('.provider');
    dragged.classList.add('dragging');
  });
  wrap.addEventListener('dragend', () => {
    dragged?.classList.remove('dragging');
    $$('.provider').forEach(c => c.classList.remove('drop-before'));
    dragged = null;
  });
  wrap.addEventListener('dragover', e => {
    e.preventDefault();
    const over = e.target.closest('.provider');
    $$('.provider').forEach(c => c.classList.remove('drop-before'));
    if (over && over !== dragged) over.classList.add('drop-before');
  });
  wrap.addEventListener('drop', e => {
    e.preventDefault();
    const over = e.target.closest('.provider');
    if (dragged && over && over !== dragged) {
      wrap.insertBefore(dragged, over);
      saveProviderOrder();
    } else if (dragged && !over) {
      wrap.appendChild(dragged);
      saveProviderOrder();
    }
  });

  wrap.addEventListener('change', e => {
    if (e.target.classList.contains('toggle')) { saveProviderOrder(); return; }
    const input = e.target.closest('[data-provider]');
    if (!input) return;
    const { provider, field, secret } = input.dataset;
    if (secret === 'true' && !input.value) return;
    api.update({ providerConfig: { [provider]: { [field]: input.value.trim() } } }).then(next => {
      state = next;
      renderProviders();
      toast(secret === 'true' ? 'Saved securely' : 'Saved');
    });
  });

  wrap.addEventListener('click', async e => {
    if (!e.target.classList.contains('test')) return;
    const card = e.target.closest('.provider');
    const out = card.querySelector('.test-result');
    out.hidden = false;
    out.textContent = 'Searching…';
    const r = await api.action('testProvider', card.dataset.id);
    out.textContent = r.text;
  });
}

/* ---------------- wiring ---------------- */

function wire() {
  for (const b of $$('nav button')) {
    b.addEventListener('click', () => {
      $$('nav button').forEach(x => x.classList.toggle('active', x === b));
      $$('.page').forEach(p => p.classList.toggle('active', p.id === `page-${b.dataset.page}`));
    });
  }

  for (const el of $$('[data-style]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.style[el.dataset.style] = v;
      setInput(el, v);
      renderPreview();
      pendingStyle[el.dataset.style] = v;
      flushStyle();
    });
  }
  for (const el of $$('[data-layout]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.layout[el.dataset.layout] = v;
      setInput(el, v);
      pendingLayout[el.dataset.layout] = v;
      flushLayout();
    });
  }
  const sendNp = debounce(patch => api.update({ nowPlaying: patch }), 80);
  let pendingNp = {};
  for (const el of $$('[data-np]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.nowPlaying = { ...(state.cfg.nowPlaying || {}), [el.dataset.np]: v };
      setInput(el, v);
      pendingNp[el.dataset.np] = v;
      const p = pendingNp; pendingNp = {};
      sendNp(p);
    });
  }
  for (const el of $$('[data-np-layout]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.layout.np = { ...(state.layout.np || {}), [el.dataset.npLayout]: v };
      setInput(el, v);
      pendingLayout.np = state.layout.np;
      flushLayout();
    });
  }
  for (const seg of $$('[data-layout-seg]')) {
    seg.addEventListener('click', e => {
      const b = e.target.closest('button');
      if (!b) return;
      state.layout[seg.dataset.layoutSeg] = b.value;
      seg.querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b));
      api.updateLayout({ [seg.dataset.layoutSeg]: b.value });
    });
  }
  for (const el of $$('[data-cfg]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg[el.dataset.cfg] = v;
      setInput(el, v);
      pendingCfg[el.dataset.cfg] = v;
      const p = pendingCfg; pendingCfg = {};
      sendCfg(p);
    });
  }

  // Picking a look also applies the style values it recommends (like a preset).
  $('#look').addEventListener('change', async e => {
    const look = e.target.value;
    const style = (state.lookStyles || {})[look];
    // the look also brings its own card
    Object.assign(state, await api.update({ look, ...(style ? { style } : {}), nowPlaying: { style: 'auto' } }));
    renderForm();
    if (style) toast(`${$('#look').selectedOptions[0].textContent} applied`);
  });
  // look cards drive the (hidden) select, arrow keys move between them
  $('#lookPicks').innerHTML = LOOK_PICKS.map(([id, name, sym]) =>
    `<button class="look-pick" role="radio" data-look="${id}"><i class="sw-${id}">${sym}</i><b>${name}</b></button>`).join('');
  const pickLook = id => { const sel = $('#look'); if (sel.value === id) return; sel.value = id; sel.dispatchEvent(new Event('change')); };
  $('#lookPicks').addEventListener('click', e => { const b = e.target.closest('.look-pick'); if (b) pickLook(b.dataset.look); });
  $('#lookPicks').addEventListener('keydown', e => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    const ids = LOOK_PICKS.map(l => l[0]);
    const i = (ids.indexOf($('#look').value) + (e.key === 'ArrowRight' ? 1 : ids.length - 1)) % ids.length;
    pickLook(ids[i]);
    setTimeout(() => $(`.look-pick[data-look="${ids[i]}"]`)?.focus(), 50);
  });
  if (state.cfg) renderLook();
  $('#accentPairs').innerHTML = ACCENT_PAIRS.map(([a, b]) =>
    `<button class="swatch" data-a1="${a}" data-a2="${b}" aria-label="${a} and ${b}"></button>`).join('');
  // CSP blocks inline style attributes; set the swatch colours through the CSSOM instead
  for (const b of $$('#accentPairs .swatch')) b.style.background = `linear-gradient(135deg, ${b.dataset.a1}, ${b.dataset.a2})`;
  $('#accentPairs').addEventListener('click', async e => {
    const b = e.target.closest('button'); if (!b) return;
    Object.assign(state, await api.update({ style: { activeColor: b.dataset.a1, activeColor2: b.dataset.a2 } }));
    renderForm();
  });
  $('#effectSeg').addEventListener('click', async e => {
    const b = e.target.closest('button'); if (!b) return;
    Object.assign(state, await api.update({ style: { effect: b.value } }));
    renderLook();
  });
  for (const el of $$('[data-deco]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.decorations = { ...(state.cfg.decorations || {}), [el.dataset.deco]: v };
      api.update({ decorations: { [el.dataset.deco]: v } });
    });
  }

  $('#display').addEventListener('change', e => api.update({ display: Number(e.target.value) }));
  $('#loginItem').addEventListener('change', e => api.action('setLoginItem', e.target.checked));

  $('#closeSeg').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    $$('#closeSeg button').forEach(x => x.classList.toggle('on', x === b));
    state.cfg.closeAction = b.value;
    api.update({ closeAction: b.value });
  });

  $('#playerSeg').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    $$('#playerSeg button').forEach(x => x.classList.toggle('on', x === b));
    $('#playerCustomRow').hidden = b.value !== 'custom';
    if (b.value !== 'custom') api.update({ player: b.value });
    else $('#playerCustom').focus();
  });
  $('#playerCustom').addEventListener('change', e => { if (e.target.value.trim()) api.update({ player: e.target.value.trim() }); });

  $('#presets').innerHTML = PRESETS.map((p, i) => `<div class="preset" data-i="${i}">${p.name}<small>${p.note}</small></div>`).join('');
  for (const el of $$('.preset')) {
    const s = PRESETS[el.dataset.i].style;
    el.style.color = s.activeColor;
    el.style.textShadow = `0 0 ${s.glow / 2}px ${s.activeColor}`;
  }
  $('#presets').addEventListener('click', e => {
    const el = e.target.closest('.preset');
    if (!el) return;
    const preset = PRESETS[el.dataset.i];
    Object.assign(state.cfg.style, preset.style);
    renderForm();
    api.update({ style: preset.style });
    toast(`${preset.name} applied`);
  });

  for (const b of $$('[data-action]')) {
    b.addEventListener('click', async () => {
      const r = await api.action(b.dataset.action);
      if (r && r.message) toast(r.message);
      if (r && r.state) { state = r.state; renderForm(); renderProviders(); }
    });
  }

  wireProviders();

  $('#compareBtn').addEventListener('click', runCompare);
  $('#compare').addEventListener('click', async e => {
    const b = e.target.closest('[data-pin]');
    if (!b) return;
    const r = await api.action('pin', b.dataset.pin);
    if (r?.message) toast(r.message);
    if (r?.state) { state = r.state; renderStatus(); }
    $$('.cmp').forEach(c => c.classList.toggle('pinned', c.querySelector('[data-pin]')?.dataset.pin === state.pinned));
    $$('[data-pin]').forEach(x => { x.textContent = x.dataset.pin === state.pinned ? 'Pinned' : 'Use for this song'; });
  });

  $('#pasteBtn').addEventListener('click', () => { $('#pasteText').value = ''; $('#pasteDialog').showModal(); });
  $('#pasteCancel').addEventListener('click', () => $('#pasteDialog').close());
  $('#pasteSave').addEventListener('click', async () => {
    const r = await api.action('pasteLyrics', $('#pasteText').value);
    $('#pasteDialog').close();
    if (r?.message) toast(r.message);
    if (r?.state) { state = r.state; renderStatus(); }
  });

  const sendTrackOffset = debounce(v => api.action('setTrackOffset', v), 150);
  $('#trackOffset').addEventListener('input', e => {
    const v = Number(e.target.value);
    setInput(e.target, v);
    sendTrackOffset(v);
  });

  api.onState(partial => {
    const layoutChanged = partial.layout && JSON.stringify(partial.layout) !== JSON.stringify(state.layout);
    Object.assign(state, partial);
    if (partial.cfg || layoutChanged) renderForm();
    else if (partial.look || partial.lookTarget) renderLook();
    if (partial.cfg) renderProviders();
    renderStatus();
  });
}

async function loadFonts() {
  try {
    const fonts = await api.fonts();
    $('#fontList').innerHTML = fonts.map(f => `<option value="${f.replace(/"/g, '&quot;')}">`).join('');
  } catch { /* free text still works */ }
}

(async () => {
  state = await api.get();
  wire();
  renderForm();
  renderProviders();
  loadFonts();
  const page = location.hash.slice(1);
  if (page) $(`nav button[data-page="${page}"]`)?.click();
})();

changes.after:
const api = window.settingsApi;
const $ = sel => document.querySelector(sel);
const $$ = sel => [...document.querySelectorAll(sel)];

let state = null;

const PRESETS = [
  { name: 'Classic', note: 'White, soft glow', style: { activeColor: '#ffffff', inactiveColor: '#ffffff', inactiveOpacity: 0.35, activeScale: 1.08, glow: 12, shadow: 6, blur: 1, bold: true } },
  { name: 'Neon', note: 'Cyan & violet', style: { activeColor: '#7df9ff', inactiveColor: '#c39bff', inactiveOpacity: 0.45, activeScale: 1.1, glow: 26, shadow: 4, blur: 0.5, bold: true } },
  { name: 'Sunset', note: 'Warm gold', style: { activeColor: '#ffd27f', inactiveColor: '#ffb3c7', inactiveOpacity: 0.4, activeScale: 1.08, glow: 18, shadow: 6, blur: 1, bold: true } },
  { name: 'Minimal', note: 'No glow, crisp', style: { activeColor: '#ffffff', inactiveColor: '#ffffff', inactiveOpacity: 0.25, activeScale: 1, glow: 0, shadow: 3, blur: 0, bold: false } },
  { name: 'Karaoke', note: 'Big yellow line', style: { activeColor: '#ffe066', inactiveColor: '#ffffff', inactiveOpacity: 0.3, activeScale: 1.2, glow: 14, shadow: 8, blur: 1.5, bold: true } },
  { name: 'Ghost', note: 'Subtle, low contrast', style: { activeColor: '#e8e4ff', inactiveColor: '#e8e4ff', inactiveOpacity: 0.15, activeScale: 1.04, glow: 6, shadow: 10, blur: 2, bold: false } },
];

/* ---------------- helpers ---------------- */

function debounce(fn, ms) {
  let t;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}

function toast(text) {
  const el = $('#toast');
  el.textContent = text;
  el.classList.add('show');
  clearTimeout(toast.t);
  toast.t = setTimeout(() => el.classList.remove('show'), 2200);
}

function valueOf(input) {
  if (input.type === 'checkbox') return input.checked;
  if (input.type === 'range' || input.type === 'number') return Number(input.value);
  return input.value;
}

function setInput(input, value) {
  if (value === undefined) return;
  if (input.type === 'checkbox') input.checked = !!value;
  else input.value = value;
  const out = input.parentElement.querySelector('output');
  if (out) out.textContent = formatOut(input, value);
}

function formatOut(input, v) {
  const step = Number(input.step || 1);
  return step < 1 ? Number(v).toFixed(step < 0.1 ? 2 : 1) : String(v);
}

const sendStyle = debounce(patch => api.update({ style: patch }), 80);
const sendLayout = debounce(patch => api.updateLayout(patch), 80);
const sendCfg = debounce(patch => api.update(patch), 80);

let pendingStyle = {}, pendingLayout = {}, pendingCfg = {};
const flushStyle = () => { const p = pendingStyle; pendingStyle = {}; sendStyle(p); };
const flushLayout = () => { const p = pendingLayout; pendingLayout = {}; sendLayout(p); };

/* ---------------- preview ---------------- */

function renderPreview() {
  const s = state.cfg.style;
  const box = $('#preview');
  box.style.fontFamily = `'${s.fontFamily}', 'Segoe UI', sans-serif`;
  box.querySelector('.pv-meta').style.display = s.showTitle ? '' : 'none';
  box.querySelector('.pv-meta').textContent = 'Song Title — Artist' + (s.showSource ? '  ·  LRCLIB' : '');
  for (const el of box.querySelectorAll('.pv-l')) {
    const active = el.classList.contains('pv-a');
    el.style.fontWeight = s.bold ? 700 : 400;
    el.style.lineHeight = s.lineHeight;
    el.style.color = active ? s.activeColor : s.inactiveColor;
    el.style.opacity = active ? 1 : s.inactiveOpacity;
    el.style.filter = active ? 'none' : `blur(${s.blur}px)`;
    el.style.transform = active ? `scale(${s.activeScale})` : 'none';
    el.style.textShadow = active
      ? `0 0 ${s.glow}px ${s.activeColor}, 0 2px ${s.shadow}px rgba(0,0,0,.9)`
      : `0 2px ${s.shadow}px rgba(0,0,0,.85)`;
  }
}

/* ---------------- render state into the form ---------------- */

// The look shown is the one in effect (the wallpaper's own one when per-wallpaper looks are on).
const ACCENT_PAIRS = [['#9b6bff', '#ff5fa2'], ['#2dd4ff', '#7b6bff'], ['#ffb347', '#ff5f6d'], ['#5be3b0', '#2a9dff']];

const LOOK_PICKS = [['classic', 'Classic', 'Aa'], ['aurora', 'Aurora', 'Aa'], ['neon', 'Neon', 'Neon'], ['magazine', 'Magazine', 'Lyric'], ['console', 'Console', '&gt;_'], ['island', 'Island', '']];

function renderLook() {
  const look = state.look || state.cfg.look || 'classic';
  $('#look').value = look;
  for (const b of $$('.look-pick')) { const on = b.dataset.look === look; b.classList.toggle('on', on); b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }
  for (const el of $$('.look-only')) el.hidden = el.dataset.for !== look;
  const pv = $('#preview');
  pv.dataset.look = look;
  pv.style.setProperty('--pv-a1', (state.cfg.style || {}).activeColor || '#9b6bff');
  pv.style.setProperty('--pv-a2', (state.cfg.style || {}).activeColor2 || '#ff5fa2');
  const st = state.cfg.style || {};
  for (const b of $$('#effectSeg button')) b.classList.toggle('on', b.value === (st.effect || 'karaoke'));
  for (const b of $$('#accentPairs button')) b.classList.toggle('on', b.dataset.a1 === st.activeColor && b.dataset.a2 === st.activeColor2);
  const t = state.lookTarget || {};
  $('#lookTarget').textContent = t.wallpaper ? `for wallpaper ${t.wallpaper}` : 'for all wallpapers';
  $('#consolePrompt').placeholder = state.consolePromptDefault || '';
}

function renderForm() {
  const { cfg, layout } = state;
  for (const el of $$('[data-style]')) setInput(el, cfg.style[el.dataset.style]);
  for (const el of $$('[data-layout]')) setInput(el, layout[el.dataset.layout]);
  for (const el of $$('[data-cfg]')) setInput(el, cfg[el.dataset.cfg]);
  for (const el of $$('[data-np]')) setInput(el, (cfg.nowPlaying || {})[el.dataset.np]);
  for (const el of $$('[data-deco]')) setInput(el, (cfg.decorations || {})[el.dataset.deco]);
  renderLook();
  for (const el of $$('[data-np-layout]')) setInput(el, (layout.np || {})[el.dataset.npLayout]);
  for (const seg of $$('[data-layout-seg]')) {
    for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.value === layout[seg.dataset.layoutSeg]);
  }

  const known = ['auto', 'Spotify', '*'];
  const isCustom = !known.includes(cfg.player);
  for (const b of $$('#playerSeg button')) b.classList.toggle('on', isCustom ? b.value === 'custom' : b.value === cfg.player);
  $('#playerCustomRow').hidden = !isCustom;
  if (isCustom && document.activeElement !== $('#playerCustom')) $('#playerCustom').value = cfg.player;

  $('#display').innerHTML = state.displays.map(d => `<option value="${d.index}">${d.label}</option>`).join('');
  $('#display').value = String(cfg.display);
  $('#loginItem').checked = state.loginItem;
  for (const b of $$('#closeSeg button')) b.classList.toggle('on', b.value === (cfg.closeAction || 'ask'));
  $('#version').textContent = state.version;
  renderStatus();
  renderPreview();
}

function renderSong() {
  const t = state.track;
  $('#songTitle').textContent = t ? `${t.title} — ${t.artist}` : 'Nothing playing';
  const pinnedName = state.pinned ? (state.providers.find(p => p.id === state.pinned)?.name || state.pinned) : null;
  $('#songSource').textContent = !t ? 'Start a song to compare sources or import lyrics.'
    : `${state.lyricsSource ? `Lyrics from ${state.lyricsSource}` : 'No lyrics found'}${pinnedName ? ` · pinned to ${pinnedName}` : ''}`;
  $('#unpinBtn').hidden = !state.pinned;
  const off = $('#trackOffset');
  if (document.activeElement !== off) setInput(off, state.trackOffsetMs || 0);
  off.disabled = !t;
}

async function runCompare() {
  const box = $('#compare');
  box.hidden = false;
  box.innerHTML = '<div class="muted small">Searching every enabled source…</div>';
  const { results = [], message } = await api.action('compare');
  if (message && !results.length) { box.innerHTML = `<div class="muted small">${message}</div>`; return; }
  box.innerHTML = '';
  for (const r of results) {
    const el = document.createElement('div');
    el.className = 'cmp' + (state.pinned === r.provider ? ' pinned' : '');
    const kind = r.error ? `error: ${r.error}` : !r.found ? (r.reason || 'nothing found')
      : `${r.synced ? `synced · ${r.lines} lines` : 'unsynced'}${r.wordSynced ? ' · word timing' : ''}`;
    el.innerHTML = `
      <div><div class="cmp-name"></div><div class="cmp-meta"></div></div>
      <div class="cmp-sample${r.found ? '' : ' none'}"></div>
      <div>${r.found ? `<button data-pin="${r.provider}">${state.pinned === r.provider ? 'Pinned' : 'Use for this song'}</button>` : ''}</div>`;
    el.querySelector('.cmp-name').textContent = r.name;
    el.querySelector('.cmp-meta').textContent = `${kind} · ${r.ms} ms${r.match ? ` · score ${r.match.score}` : ''}`;
    el.querySelector('.cmp-sample').textContent = r.found ? r.sample.join('\n') : '—';
    box.appendChild(el);
  }
}

function renderUpdate() {
  const u = state.update || {};
  const text = {
    checking: 'Checking for updates…',
    latest: `You're on the latest version (${state.version}).`,
    available: u.canInstall ? `Downloading ${u.version}…` : `Version ${u.version} is out — download it from GitHub.`,
    downloading: `Downloading ${u.version}…`,
    ready: `Version ${u.version} is ready.`,
    error: `Update check failed: ${u.error}`,
  }[u.status] || `Version ${state.version}`;
  $('#updateStatus').textContent = text;
  $('#installUpdate').hidden = u.status !== 'ready';
}

function renderStatus() {
  renderSong();
  renderUpdate();
  const art = $('#nowArt');
  if (state.art) { art.src = state.art; art.hidden = false; } else { art.hidden = true; art.removeAttribute('src'); }
  const t = state.track;
  $('#nowTitle').textContent = t ? `${t.title} — ${t.artist}` : 'Nothing playing';
  $('#nowSource').textContent = t ? `${t.player || 'player'} · ${state.lyricsSource || 'no lyrics'}` : '';
  $('#layoutTarget').textContent = `· saved for ${state.layoutTarget}`;
  $('#wallpaperInfo').textContent = state.wallpaperKey
    ? `Current Wallpaper Engine wallpaper: ${state.wallpaperKey}`
    : 'No Wallpaper Engine wallpaper detected — the default layout is used.';
  for (const card of $$('.provider')) {
    const badge = card.querySelector('.badge.current');
    if (badge) badge.hidden = state.lyricsSourceId !== card.dataset.id;
  }
}

/* ---------------- providers ---------------- */

function providerList() {
  return state.cfg.providers.filter(p => state.providers.some(r => r.id === p.id));
}

function renderProviders() {
  const wrap = $('#providers');
  wrap.innerHTML = '';
  providerList().forEach((entry, i) => {
    const info = state.providers.find(p => p.id === entry.id);
    const card = document.createElement('div');
    card.className = 'provider';
    card.dataset.id = entry.id;
    card.draggable = true;
    const secrets = (state.secretsSet || {})[entry.id] || {};
    const conf = state.cfg.providerConfig[entry.id] || {};
    const needsSetup = info.fields.some(f => f.required && !(f.type === 'secret' ? secrets[f.key] : conf[f.key]));
    card.innerHTML = `
      <div class="provider-head">
        <span class="grip" title="Drag to reorder">⠿</span>
        <span class="prio">${i + 1}</span>
        <div>
          <div class="provider-name">${info.name}</div>
          <div class="provider-desc">${info.description}</div>
        </div>
        <span class="spacer"></span>
        <span class="badge current" hidden>in use</span>
        ${needsSetup ? '<span class="badge warn">needs setup</span>' : ''}
        <button class="test">Test</button>
        <input type="checkbox" class="switch toggle" ${entry.enabled ? 'checked' : ''}>
      </div>
      ${info.fields.length ? `<div class="provider-body">${info.fields.map(f => fieldHtml(entry.id, f, conf, secrets)).join('')}</div>` : ''}
      <div class="test-result" hidden></div>`;
    wrap.appendChild(card);
  });
  renderStatus();
}

function fieldHtml(id, f, conf, secrets) {
  const isSecret = f.type === 'secret';
  const value = isSecret ? '' : (conf[f.key] ?? '');
  const placeholder = isSecret ? (secrets[f.key] ? 'Saved — paste a new value to replace' : f.placeholder || '') : f.placeholder || '';
  return `
    <label class="row">${f.label}
      <input data-provider="${id}" data-field="${f.key}" data-secret="${isSecret}" type="${isSecret ? 'password' : 'text'}"
             value="${String(value).replace(/"/g, '&quot;')}" placeholder="${placeholder}" spellcheck="false">
    </label>
    ${f.help ? `<div class="help">${f.help}</div>` : ''}`;
}

function saveProviderOrder() {
  const order = $$('.provider').map(c => ({ id: c.dataset.id, enabled: c.querySelector('.toggle').checked }));
  const rest = state.cfg.providers.filter(p => !order.some(o => o.id === p.id));
  state.cfg.providers = [...order, ...rest];
  api.update({ providers: state.cfg.providers });
  $$('.provider .prio').forEach((el, i) => { el.textContent = i + 1; });
}

function wireProviders() {
  const wrap = $('#providers');
  let dragged = null;

  wrap.addEventListener('dragstart', e => {
    dragged = e.target.closest('.provider');
    dragged.classList.add('dragging');
  });
  wrap.addEventListener('dragend', () => {
    dragged?.classList.remove('dragging');
    $$('.provider').forEach(c => c.classList.remove('drop-before'));
    dragged = null;
  });
  wrap.addEventListener('dragover', e => {
    e.preventDefault();
    const over = e.target.closest('.provider');
    $$('.provider').forEach(c => c.classList.remove('drop-before'));
    if (over && over !== dragged) over.classList.add('drop-before');
  });
  wrap.addEventListener('drop', e => {
    e.preventDefault();
    const over = e.target.closest('.provider');
    if (dragged && over && over !== dragged) {
      wrap.insertBefore(dragged, over);
      saveProviderOrder();
    } else if (dragged && !over) {
      wrap.appendChild(dragged);
      saveProviderOrder();
    }
  });

  wrap.addEventListener('change', e => {
    if (e.target.classList.contains('toggle')) { saveProviderOrder(); return; }
    const input = e.target.closest('[data-provider]');
    if (!input) return;
    const { provider, field, secret } = input.dataset;
    if (secret === 'true' && !input.value) return;
    api.update({ providerConfig: { [provider]: { [field]: input.value.trim() } } }).then(next => {
      state = next;
      renderProviders();
      toast(secret === 'true' ? 'Saved securely' : 'Saved');
    });
  });

  wrap.addEventListener('click', async e => {
    if (!e.target.classList.contains('test')) return;
    const card = e.target.closest('.provider');
    const out = card.querySelector('.test-result');
    out.hidden = false;
    out.textContent = 'Searching…';
    const r = await api.action('testProvider', card.dataset.id);
    out.textContent = r.text;
  });
}

/* ---------------- wiring ---------------- */

function wire() {
  for (const b of $$('nav button')) {
    b.addEventListener('click', () => {
      $$('nav button').forEach(x => x.classList.toggle('active', x === b));
      $$('.page').forEach(p => p.classList.toggle('active', p.id === `page-${b.dataset.page}`));
    });
  }

  for (const el of $$('[data-style]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.style[el.dataset.style] = v;
      setInput(el, v);
      renderPreview();
      pendingStyle[el.dataset.style] = v;
      flushStyle();
    });
  }
  for (const el of $$('[data-layout]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.layout[el.dataset.layout] = v;
      setInput(el, v);
      pendingLayout[el.dataset.layout] = v;
      flushLayout();
    });
  }
  const sendNp = debounce(patch => api.update({ nowPlaying: patch }), 80);
  let pendingNp = {};
  for (const el of $$('[data-np]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.nowPlaying = { ...(state.cfg.nowPlaying || {}), [el.dataset.np]: v };
      setInput(el, v);
      pendingNp[el.dataset.np] = v;
      const p = pendingNp; pendingNp = {};
      sendNp(p);
    });
  }
  for (const el of $$('[data-np-layout]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.layout.np = { ...(state.layout.np || {}), [el.dataset.npLayout]: v };
      setInput(el, v);
      pendingLayout.np = state.layout.np;
      flushLayout();
    });
  }
  for (const seg of $$('[data-layout-seg]')) {
    seg.addEventListener('click', e => {
      const b = e.target.closest('button');
      if (!b) return;
      state.layout[seg.dataset.layoutSeg] = b.value;
      seg.querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b));
      api.updateLayout({ [seg.dataset.layoutSeg]: b.value });
    });
  }
  for (const el of $$('[data-cfg]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg[el.dataset.cfg] = v;
      setInput(el, v);
      pendingCfg[el.dataset.cfg] = v;
      const p = pendingCfg; pendingCfg = {};
      sendCfg(p);
    });
  }

  // Picking a look also applies the style values it recommends (like a preset).
  $('#look').addEventListener('change', async e => {
    const look = e.target.value;
    const style = (state.lookStyles || {})[look];
    // the look also brings its own card
    Object.assign(state, await api.update({ look, ...(style ? { style } : {}), nowPlaying: { style: 'auto' } }));
    renderForm();
    if (style) toast(`${$('#look').selectedOptions[0].textContent} applied`);
  });
  // look cards drive the (hidden) select, arrow keys move between them
  $('#lookPicks').innerHTML = LOOK_PICKS.map(([id, name, sym]) =>
    `<button class="look-pick" role="radio" data-look="${id}"><i class="sw-${id}">${sym}</i><b>${name}</b></button>`).join('');
  const pickLook = id => { const sel = $('#look'); if (sel.value === id) return; sel.value = id; sel.dispatchEvent(new Event('change')); };
  $('#lookPicks').addEventListener('click', e => { const b = e.target.closest('.look-pick'); if (b) pickLook(b.dataset.look); });
  $('#lookPicks').addEventListener('keydown', e => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    const ids = LOOK_PICKS.map(l => l[0]);
    const i = (ids.indexOf($('#look').value) + (e.key === 'ArrowRight' ? 1 : ids.length - 1)) % ids.length;
    pickLook(ids[i]);
    setTimeout(() => $(`.look-pick[data-look="${ids[i]}"]`)?.focus(), 50);
  });
  if (state.cfg) renderLook();
  $('#accentPairs').innerHTML = ACCENT_PAIRS.map(([a, b]) =>
    `<button class="swatch" data-a1="${a}" data-a2="${b}" aria-label="${a} and ${b}"></button>`).join('');
  // CSP blocks inline style attributes; set the swatch colours through the CSSOM instead
  for (const b of $$('#accentPairs .swatch')) b.style.background = `linear-gradient(135deg, ${b.dataset.a1}, ${b.dataset.a2})`;
  $('#accentPairs').addEventListener('click', async e => {
    const b = e.target.closest('button'); if (!b) return;
    Object.assign(state, await api.update({ style: { activeColor: b.dataset.a1, activeColor2: b.dataset.a2 } }));
    renderForm();
  });
  $('#effectSeg').addEventListener('click', async e => {
    const b = e.target.closest('button'); if (!b) return;
    Object.assign(state, await api.update({ style: { effect: b.value } }));
    renderLook();
  });
  for (const el of $$('[data-deco]')) {
    el.addEventListener('input', () => {
      const v = valueOf(el);
      state.cfg.decorations = { ...(state.cfg.decorations || {}), [el.dataset.deco]: v };
      api.update({ decorations: { [el.dataset.deco]: v } });
    });
  }

  $('#checkUpdates').addEventListener('click', async () => { state.update = await api.action('checkUpdates'); renderUpdate(); });
  $('#installUpdate').addEventListener('click', () => api.action('installUpdate'));

  $('#display').addEventListener('change', e => api.update({ display: Number(e.target.value) }));
  $('#loginItem').addEventListener('change', e => api.action('setLoginItem', e.target.checked));

  $('#closeSeg').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    $$('#closeSeg button').forEach(x => x.classList.toggle('on', x === b));
    state.cfg.closeAction = b.value;
    api.update({ closeAction: b.value });
  });

  $('#playerSeg').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    $$('#playerSeg button').forEach(x => x.classList.toggle('on', x === b));
    $('#playerCustomRow').hidden = b.value !== 'custom';
    if (b.value !== 'custom') api.update({ player: b.value });
    else $('#playerCustom').focus();
  });
  $('#playerCustom').addEventListener('change', e => { if (e.target.value.trim()) api.update({ player: e.target.value.trim() }); });

  $('#presets').innerHTML = PRESETS.map((p, i) => `<div class="preset" data-i="${i}">${p.name}<small>${p.note}</small></div>`).join('');
  for (const el of $$('.preset')) {
    const s = PRESETS[el.dataset.i].style;
    el.style.color = s.activeColor;
    el.style.textShadow = `0 0 ${s.glow / 2}px ${s.activeColor}`;
  }
  $('#presets').addEventListener('click', e => {
    const el = e.target.closest('.preset');
    if (!el) return;
    const preset = PRESETS[el.dataset.i];
    Object.assign(state.cfg.style, preset.style);
    renderForm();
    api.update({ style: preset.style });
    toast(`${preset.name} applied`);
  });

  for (const b of $$('[data-action]')) {
    b.addEventListener('click', async () => {
      const r = await api.action(b.dataset.action);
      if (r && r.message) toast(r.message);
      if (r && r.state) { state = r.state; renderForm(); renderProviders(); }
    });
  }

  wireProviders();

  $('#compareBtn').addEventListener('click', runCompare);
  $('#compare').addEventListener('click', async e => {
    const b = e.target.closest('[data-pin]');
    if (!b) return;
    const r = await api.action('pin', b.dataset.pin);
    if (r?.message) toast(r.message);
    if (r?.state) { state = r.state; renderStatus(); }
    $$('.cmp').forEach(c => c.classList.toggle('pinned', c.querySelector('[data-pin]')?.dataset.pin === state.pinned));
    $$('[data-pin]').forEach(x => { x.textContent = x.dataset.pin === state.pinned ? 'Pinned' : 'Use for this song'; });
  });

  $('#pasteBtn').addEventListener('click', () => { $('#pasteText').value = ''; $('#pasteDialog').showModal(); });
  $('#pasteCancel').addEventListener('click', () => $('#pasteDialog').close());
  $('#pasteSave').addEventListener('click', async () => {
    const r = await api.action('pasteLyrics', $('#pasteText').value);
    $('#pasteDialog').close();
    if (r?.message) toast(r.message);
    if (r?.state) { state = r.state; renderStatus(); }
  });

  const sendTrackOffset = debounce(v => api.action('setTrackOffset', v), 150);
  $('#trackOffset').addEventListener('input', e => {
    const v = Number(e.target.value);
    setInput(e.target, v);
    sendTrackOffset(v);
  });

  api.onState(partial => {
    const layoutChanged = partial.layout && JSON.stringify(partial.layout) !== JSON.stringify(state.layout);
    Object.assign(state, partial);
    if (partial.cfg || layoutChanged) renderForm();
    else if (partial.look || partial.lookTarget) renderLook();
    if (partial.cfg) renderProviders();
    renderStatus();
  });
}

async function loadFonts() {
  try {
    const fonts = await api.fonts();
    $('#fontList').innerHTML = fonts.map(f => `<option value="${f.replace(/"/g, '&quot;')}">`).join('');
  } catch { /* free text still works */ }
}

(async () => {
  state = await api.get();
  wire();
  renderForm();
  renderProviders();
  loadFonts();
  const page = location.hash.slice(1);
  if (page) $(`nav button[data-page="${page}"]`)?.click();
})();

