const fs = require('fs');
const path = require('path');

// Overlay looks (docs/design/THEMES-PLAN.md). "classic" is the look from before looks existed.
const LOOKS = ['classic', 'aurora', 'neon', 'magazine', 'console', 'island'];

// Style values a look recommends; applied when the look is picked (sliders still work after).
const LOOK_STYLES = {
  classic: { activeColor: '#ffffff', activeColor2: '', inactiveColor: '#ffffff', inactiveOpacity: 0.35, activeScale: 1.08, glow: 12, shadow: 6, blur: 1, bold: true },
  neon: { activeColor: '#ff3dc8', activeColor2: '#2ef2ff', inactiveColor: '#ff8ee0', inactiveOpacity: 0.45, activeScale: 1, glow: 18, shadow: 4, blur: 0, bold: false },
  magazine: { activeColor: '#eef3ee', activeColor2: '#f2c14e', inactiveColor: '#eef3ee', inactiveOpacity: 0.5, activeScale: 1, glow: 0, shadow: 6, blur: 0, bold: false },
  console: { activeColor: '#d4ffdd', activeColor2: '#7dff9b', inactiveColor: '#7dff9b', inactiveOpacity: 0.55, activeScale: 1, glow: 8, shadow: 0, blur: 0, bold: false },
  island: { activeColor: '#ffffff', activeColor2: '#ff6b9d', inactiveColor: '#ffffff', inactiveOpacity: 0.35, activeScale: 1, glow: 0, shadow: 0, blur: 0, bold: true },
  aurora: { activeColor: '#9b6bff', activeColor2: '#ff5fa2', inactiveColor: '#ffffff', inactiveOpacity: 0.28, activeScale: 1, glow: 14, shadow: 6, blur: 1.5, bold: true, effect: 'karaoke' },
};

const DEFAULTS = {
  settingsVersion: 2,
  // New installs start on Aurora; settings files from before looks existed get "classic" (see load()).
  look: 'aurora',
  // Optionally a different look per Wallpaper Engine wallpaper: { "<workshop id>": "neon" }.
  perWallpaperLook: false,
  wallpaperLooks: {},
  // Look decorations, each switchable.
  decorations: { meta: true, onAir: true, trackNumber: true, scanlines: true, eq: true },
  // Console look prompt; empty = "<Windows user>@<computer name>".
  consolePrompt: '',

  // Substring of the media app id. "Spotify" matches the Spotify desktop app. "*" = any player.
  player: 'auto',
  // Index of the monitor to draw on (0 = first).
  display: 0,
  // Shifts the lyrics in time. Positive = lyrics appear earlier.
  offsetMs: 0,
  hideWhenPaused: false,
  // Desktop layer by default; true keeps the overlay above all windows (still click-through).
  alwaysOnTop: false,
  // Remember a separate position/size for each Wallpaper Engine wallpaper.
  perWallpaperLayout: true,
  wallpaperEngineConfig: 'C:\\Program Files (x86)\\Steam\\steamapps\\common\\wallpaper_engine\\config.json',

  // Default layout (used when the current wallpaper has no saved layout).
  // x / y = center of the lyrics block in % of the screen, width in % of the screen.
  layout: {
    x: 50, y: 50, width: 45, align: 'center', lines: 7, fontSize: 34,
    // Now-playing card: top-left corner in % of the screen, art size in px.
    np: { x: 2, y: 4, size: 88 },
  },

  nowPlaying: {
    show: true,
    style: 'auto',        // auto (the look's own card) | ambient (blurred cover) | vinyl | caption
    hideWhenIdle: true,   // hide when nothing is playing
    card: true,           // translucent card behind it
    cardOpacity: 0.35,
    cardBlur: 28,
    radius: 14,
    showAlbum: false,
    showProgress: true,
    accentFromArt: true,  // progress bar color from the album art
  },

  style: {
    fontFamily: 'Segoe UI',
    bold: true,
    lineHeight: 1.35,
    activeColor: '#ffffff',
    inactiveColor: '#ffffff',
    inactiveOpacity: 0.35,
    activeScale: 1.08,
    glow: 12,
    shadow: 6,
    blur: 1,
    animationMs: 450,
    showTitle: true,
    showSource: false,
    showUnsynced: true,
    showTranslation: false,
    showRomanization: false,
    wordHighlight: true,
    activeColor2: '',     // second accent for gradient word fills; empty = the look's default
    effect: 'karaoke',    // karaoke | glow | clean (Aurora)
  },

  // Lyrics sources, tried in this order (all run in parallel, first synced result by priority wins).
  providers: [
    { id: 'local', enabled: true },
    { id: 'spotify', enabled: false },
    { id: 'lrclib', enabled: true },
    { id: 'musixmatch', enabled: true },
    { id: 'netease', enabled: true },
    { id: 'qqmusic', enabled: true },
    { id: 'applemusic', enabled: false },
    { id: 'genius', enabled: true },
  ],
  // What the window's X button does: 'ask' | 'tray' | 'quit'.
  closeAction: 'ask',
  // Wait briefly for a lower-priority source with word timing before settling on line timing.
  preferWordTiming: true,
  // Per-provider options and credentials (credentials are encrypted with Windows DPAPI via safeStorage).
  providerConfig: {},
  // { "<artist>|<title>": { provider: "netease" } } — pin a source for a song.
  trackOverrides: {},
  // { "<artist>|<title>": 250 } — extra timing offset for one song (ms, + = earlier).
  trackOffsets: {},

  // Filled automatically in edit mode, keyed by Wallpaper Engine workshop id.
  wallpaperLayouts: {},
};

// Keeps the user's order and switches, adds providers that are new in this version.
function normalizeProviders(list) {
  const known = new Set();
  const out = [];
  for (const p of Array.isArray(list) ? list : []) {
    if (p && typeof p.id === 'string' && !known.has(p.id)) { known.add(p.id); out.push({ id: p.id, enabled: !!p.enabled }); }
  }
  for (const p of DEFAULTS.providers) if (!known.has(p.id)) out.push({ ...p });
  return out;
}

// electron is required lazily so the pure helpers can be unit-tested in plain node.
const file = () => path.join(require('electron').app.getPath('userData'), 'settings.json');
let ignoreUntil = 0;

function merge(def, val) {
  if (def === null || typeof def !== 'object' || Array.isArray(def)) return val === undefined ? def : val;
  const out = { ...def };
  if (val && typeof val === 'object') {
    for (const k of Object.keys(val)) out[k] = k in def ? merge(def[k], val[k]) : val[k];
  }
  return out;
}

function load() {
  const f = file();
  if (!fs.existsSync(f)) {
    const fresh = structuredClone(DEFAULTS);
    Object.assign(fresh.style, LOOK_STYLES[fresh.look] || {});
    save(fresh);
    return fresh;
  }
  const text = fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, '');
  const raw = JSON.parse(text);
  const cfg = merge(DEFAULTS, raw);
  cfg.providers = normalizeProviders(cfg.providers);
  // Existing setups keep the look they had before looks existed.
  if (!raw || !('look' in raw)) {
    cfg.look = 'classic';
    // before looks, 'ambient' was simply the default card; let the look decide (same result for classic)
    if (cfg.nowPlaying.style === 'ambient') cfg.nowPlaying.style = 'auto';
  }
  if (!LOOKS.includes(cfg.look)) cfg.look = 'classic';
  // settings v2: "Spotify" was the default player before "auto" existed; auto still prefers Spotify
  if ((raw.settingsVersion || 1) < 2 && cfg.player === 'Spotify') cfg.player = 'auto';
  cfg.settingsVersion = 2;
  return cfg;
}

function save(cfg) {
  ignoreUntil = Date.now() + 1500;
  fs.mkdirSync(path.dirname(file()), { recursive: true });
  fs.writeFileSync(file(), JSON.stringify(cfg, null, 2), 'utf8');
}

function watch(onChange) {
  fs.watchFile(file(), { interval: 1000 }, () => {
    if (Date.now() < ignoreUntil) return;
    try {
      onChange(load());
    } catch (e) {
      console.error('settings.json could not be read, keeping previous settings:', e.message);
    }
  });
}

/** The look in effect: the wallpaper's own look (if enabled and set), else the global one. */
function effectiveLook(cfg, wallpaperKey) {
  const own = cfg.perWallpaperLook && wallpaperKey ? (cfg.wallpaperLooks || {})[wallpaperKey] : null;
  if (LOOKS.includes(own)) return own;
  return LOOKS.includes(cfg.look) ? cfg.look : 'classic';
}

/** Where a look change should be stored: { wallpaper: key } or { global: true }. */
function lookTarget(cfg, wallpaperKey) {
  return cfg.perWallpaperLook && wallpaperKey ? { wallpaper: wallpaperKey } : { global: true };
}

module.exports = { DEFAULTS, LOOKS, LOOK_STYLES, load, save, watch, file, merge, normalizeProviders, effectiveLook, lookTarget };

