  return cfg;
}

function save(cfg) {
  ignoreUntil = Date.now() + 1500;
  fs.mkdirSync(path.dirname(file()), { recursive: true });
  fs.writeFileSync(file(), JSON.stringify(cfg, null, 2), 'utf8');
}

function watch(onChange) {
  fs.watchFile(file(), { interval: 1000 }, () => {
    if (Date.now() < ignoreUntil) return;
    try {
      onChange(load());
    } catch (e) {
      console.error('settings.json could not be read, keeping previous settings:', e.message);
    }
  });
}

/** The look in effect: the wallpaper's own look (if enabled and set), else the global one. */
function effectiveLook(cfg, wallpaperKey) {
  const own = cfg.perWallpaperLook && wallpaperKey ? (cfg.wallpaperLooks || {})[wallpaperKey] : null;
  if (LOOKS.includes(own)) return own;
  return LOOKS.includes(cfg.look) ? cfg.look : 'classic';
}

/** Where a look change should be stored: { wallpaper: key } or { global: true }. */
function lookTarget(cfg, wallpaperKey) {
  return cfg.perWallpaperLook && wallpaperKey ? { wallpaper: wallpaperKey } : { global: true };
}

module.exports = { DEFAULTS, LOOKS, LOOK_STYLES, load, save, watch, file, merge, normalizeProviders, effectiveLook, lookTarget };

// Self-update from GitHub Releases, no extra dependencies.
// Installed builds: check → download the new setup.exe in the background → "Restart to update"
// runs it silently (/S --force-run starts the app again afterwards). Portable builds can't replace
// themselves, so they only report that a new version exists.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawn } = require('child_process');

const REPO = 'velibkolay/desktop-lyrics';
const API = `https://api.github.com/repos/${REPO}/releases/latest`;

/** -1 / 0 / 1 for "1.2.3"-style versions (a leading "v" is ignored). */
function compareVersions(a, b) {
  const pa = String(a).replace(/^v/i, '').split('.').map(n => parseInt(n, 10) || 0);
  const pb = String(b).replace(/^v/i, '').split('.').map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return d > 0 ? 1 : -1;
  }
  return 0;
}

/** From a GitHub "latest release" response: the newer version and its installer, or null. */
function pickUpdate(release, currentVersion) {
  if (!release || release.draft || release.prerelease) return null;
  const version = String(release.tag_name || '').replace(/^v/i, '');
  if (!version || compareVersions(version, currentVersion) <= 0) return null;
  const asset = (release.assets || []).find(a => /-setup\.exe$/i.test(a.name));
  return {
    version,
    url: release.html_url,
    asset: asset ? { name: asset.name, size: asset.size, href: asset.browser_download_url, sha256: String(asset.digest || '').replace(/^sha256:/, '') || null } : null,
  };
}

function createUpdater({ app, log = console.log, onChange = () => {} }) {
  const portable = !!process.env.PORTABLE_EXECUTABLE_FILE;
  const canInstall = app.isPackaged && !portable;
  let state = { status: 'idle', version: null, url: null, error: null, canInstall };
  let file = null;
  let busy = false;

  const set = patch => { state = { ...state, ...patch }; onChange(state); };

  async function download(asset) {
    const dir = path.join(app.getPath('temp'), 'desktop-lyrics-update');
    fs.mkdirSync(dir, { recursive: true });
    const target = path.join(dir, asset.name);
    if (fs.existsSync(target) && fs.statSync(target).size === asset.size) return target; // already here
    set({ status: 'downloading' });
    const res = await fetch(asset.href, { headers: { 'User-Agent': 'desktop-lyrics' } });
    if (!res.ok) throw new Error(`download failed: HTTP ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    if (asset.size && buf.length !== asset.size) throw new Error('download incomplete');
    if (asset.sha256 && crypto.createHash('sha256').update(buf).digest('hex') !== asset.sha256) throw new Error('download corrupt (checksum)');
    fs.writeFileSync(target, buf);
    return target;
  }

  async function check({ manual = false } = {}) {
    if (busy || state.status === 'ready') return state;
    busy = true;
    try {
      if (manual) set({ status: 'checking', error: null });
      const res = await fetch(API, { headers: { 'User-Agent': 'desktop-lyrics', Accept: 'application/vnd.github+json' } });
      if (!res.ok) throw new Error(`update check failed: HTTP ${res.status}`);
      const update = pickUpdate(await res.json(), app.getVersion());
      if (!update) { set({ status: 'latest', version: null, error: null }); return state; }
      set({ status: 'available', version: update.version, url: update.url, error: null });
      log(`[update] ${update.version} available`);
      if (canInstall && update.asset) {
        file = await download(update.asset);
        set({ status: 'ready' });
        log(`[update] ${update.version} downloaded, installs on restart`);
      }
    } catch (e) {
      set({ status: 'error', error: e.message });
      log(`[update] ${e.message}`);
    } finally {
      busy = false;
    }
    return state;
  }

  /** Runs the downloaded installer silently; it restarts the app when it's done. */
  function install() {
    if (state.status !== 'ready' || !file || !fs.existsSync(file)) return false;
    log(`[update] installing ${state.version}`);
    spawn(file, ['/S', '--force-run'], { detached: true, stdio: 'ignore' }).unref();
    app.quit();
    return true;
  }

  return { check, install, get state() { return state; } };
}

module.exports = { createUpdater, compareVersions, pickUpdate };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { compareVersions, pickUpdate } = require('../src/updater');

test('version compare', () => {
  assert.equal(compareVersions('0.7.0', '0.6.0'), 1);
  assert.equal(compareVersions('v0.6.0', '0.6.0'), 0);
  assert.equal(compareVersions('0.6.0', '0.10.0'), -1, 'numeric, not string order');
  assert.equal(compareVersions('1.0', '0.9.9'), 1);
});

const release = (tag, assets = [{ name: `Desktop-Lyrics-${tag.slice(1)}-setup.exe`, size: 10, browser_download_url: 'https://x/setup.exe', digest: 'sha256:abc' }, { name: 'Desktop-Lyrics-x-portable.exe', size: 9, browser_download_url: 'https://x/p.exe' }]) =>
  ({ tag_name: tag, html_url: `https://github.com/r/releases/tag/${tag}`, assets });

test('picks a newer release and its setup.exe', () => {
  const u = pickUpdate(release('v0.7.0'), '0.6.0');
  assert.equal(u.version, '0.7.0');
  assert.equal(u.asset.name, 'Desktop-Lyrics-0.7.0-setup.exe');
  assert.equal(u.asset.sha256, 'abc');
});

test('no update when the release is not newer, a draft, or a prerelease', () => {
  assert.equal(pickUpdate(release('v0.6.0'), '0.6.0'), null);
  assert.equal(pickUpdate(release('v0.5.0'), '0.6.0'), null);
  assert.equal(pickUpdate({ ...release('v0.9.0'), prerelease: true }, '0.6.0'), null);
  assert.equal(pickUpdate({ ...release('v0.9.0'), draft: true }, '0.6.0'), null);
  assert.equal(pickUpdate(null, '0.6.0'), null);
});

test('a newer release without an installer is still reported (no asset)', () => {
  const u = pickUpdate(release('v0.8.0', []), '0.6.0');
  assert.equal(u.version, '0.8.0');
  assert.equal(u.asset, null);
});
